window.BANK=[{"id": "L13-2001", "codes": ["L13102"], "diff": "易", "level": "理解", "stem": "黃昏轉入夜晚時，花園裡的紅花看起來越來越暗，藍綠色的葉子反而顯得相對較亮。下列解釋何者正確？", "opts": ["光線變暗後紅花的色料會吸收更多長波長光，使紅花的反射率下降", "光線變暗後瞳孔放大，進入眼睛的短波長光比例增加，使藍綠色葉子顯得較亮", "光線變暗後改由桿狀細胞主導，敏感峰值由 555 nm 移向 507 nm", "這是色彩同化：葉子的藍綠色擴散到紅花上，使紅花看起來偏暗"], "explain": "明視覺 V(λ) 峰值在 555 nm，暗視覺 V′(λ) 峰值在 507 nm。亮度降低時，視覺敏感度往短波長移動，長波長的紅相對變暗（浦肯野效應）。", "trap": "物體反射率不會隨光量改變；瞳孔大小只改變進光量、不改變光譜比例；同化是空間上的色彩混合，與光線變暗無關。", "src": "科目三指引 1.1（第 2-3 頁）；吳瑞卿簡報（柏金赫效應）", "fam": "L13-2001", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2002", "codes": ["L13104"], "diff": "易", "level": "應用", "stem": "以濃度計量測某印刷色塊，得到反射率 R = 0.01。其反射濃度 D 為多少？", "opts": ["0.01", "2.0", "1.0", "100"], "explain": "反射濃度 D = log₁₀(1/R) = log₁₀(100) = 2.0。純白（R≈1）的濃度約為 0。", "trap": "0.01 與 100 是把 R 或 1/R 直接當答案，沒有取對數。", "src": "科目三指引 2.1（第 2-32 頁）", "fam": "density", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2003", "codes": ["L13101"], "diff": "易", "level": "知識", "stem": "CIE 標準照明體 D65 指的是下列何者？", "opts": ["相關色溫約 5000 K 的代表性日光", "相關色溫 2856 K 的鎢絲燈（白熾燈）", "各波長能量相等的等能白光", "相關色溫約 6500 K 的代表性日光"], "explain": "D 系列是 CIE 以公式定義的日光，D65 對應約 6500 K；A 為鎢絲燈 2856 K，E 為等能白光，F 系列為螢光燈。", "trap": "誘答分別對應 D50、A、E 照明體；D50 與 D65 同屬日光系列，只差在色溫，檢查學生能否分清代號。", "src": "科目三指引 1.2（第 2-8～2-9 頁）", "fam": "L13-2003", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2004", "codes": ["L13203"], "diff": "易", "level": "理解", "stem": "一般 LCD 液晶顯示器呈現白色畫面的原理，下列敘述何者正確？", "opts": ["背光經 RGB 彩色濾光片形成子畫素，以並置加法混色合成白色", "紅、綠、藍色光依時間快速輪流出現，以時序混色（繼時加法混色）合成白色", "每個畫素的有機發光層直接發出白光，再由液晶控制亮暗", "背光經紅、綠、藍彩色濾光片重疊，以減法混色過濾成白色"], "explain": "LCD 不自發光，背光通過液晶與 RGB 彩色濾光片，相鄰的極小子畫素超出眼睛空間解析力，形成並置加法混色。", "trap": "時序混色是單晶片 DLP 的機制；自發光是 OLED；濾光片重疊是減法混色的典型迷思。", "src": "科目一指引 2.7（第 2-38、2-40 頁）；陳鴻興簡報", "fam": "L13-2004", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2005", "codes": ["L13205"], "diff": "易", "level": "理解", "stem": "四色印刷在 CMY 之外加入黑版（K），下列何者「不是」加入黑版的目的？", "opts": ["提高暗部濃度與明暗對比", "讓灰色平衡更穩定", "擴大印刷在青綠色區域的色域", "避免黑色細線因三色套印不準而出現彩色邊緣"], "explain": "黑版主要用於暗部濃度、灰平衡與細線品質；它是無彩色，無法擴大青綠等彩色區域的色域。", "trap": "青綠色域常和「印刷色域在青綠區超出 sRGB」的知識混在一起，是刻意的錯置。", "src": "科目三指引 2.3（第 2-46 頁）", "fam": "L13-2005", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2006", "codes": ["L13303"], "diff": "易", "level": "知識", "stem": "ICC 色彩管理架構中，「描述檔連接空間」（PCS）採用的是？", "opts": ["以 D50 為參考白的 CIELAB 或 CIEXYZ", "以 D65 為參考白的 CIELAB 或 CIEXYZ", "sRGB，因為它是最通用的標準 RGB 色彩空間", "YCbCr，以亮度與色差分離的方式描述色彩"], "explain": "ICC 規定 PCS 是裝置無關空間，參考白為 D50，可用 CIELAB 或 CIEXYZ 表示。", "trap": "D65 是 sRGB 與顯示器常見白點，最容易被誤認為 PCS 的白點；sRGB 與 YCbCr 都不是 ICC 規定的 PCS。", "src": "科目三指引 2.3（第 2-44 頁）；徐明景簡報", "fam": "L13-2006", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2007", "codes": ["L13302"], "diff": "易", "level": "知識", "stem": "色彩管理的「3C」，正確的執行順序為何？", "opts": ["特性描述 → 校準 → 轉換", "轉換 → 校準 → 特性描述", "校準 → 轉換 → 特性描述", "校準 → 特性描述 → 轉換"], "explain": "先讓裝置回到穩定標準狀態（校準），再量測建立訊號與色度的關係（特性描述，產出描述檔），最後才能做轉換。", "trap": "把特性描述放在校準前，代表描述的是不穩定的狀態，描述檔很快就失效。", "src": "科目一指引 2.6；徐明景簡報", "fam": "L13-2007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2008", "codes": ["L13206"], "diff": "易", "level": "理解", "stem": "染廠預測新配方的顏色時，常把反射率換算成 K/S 值來計算，而不直接把各染料的反射率相加。原因是？", "opts": ["反射率與染料濃度成正比，但量測誤差大，需換算成 K/S 以降低誤差", "K/S 與染料濃度近似成正比，可依配方比例相加", "K/S 值就是 CIELAB 的明度 L*，可直接用來比較顏色深淺", "K/S 與染料濃度成反比，濃度越高 K/S 越小，便於修色計算"], "explain": "Kubelka–Munk 理論以吸收係數 K 與散射係數 S 描述色料，K/S 與色料濃度近似呈線性、可依配方加總，再換回反射率，因此廣泛用於紡織配色與修色。", "trap": "反射率與濃度並非線性；K/S 不是明度；K/S 隨濃度增加而變大，方向弄反是常見錯誤。", "src": "科目三指引 2.3（第 2-48 頁）", "fam": "L13-2008", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2009", "codes": ["L13101", "L13103"], "diff": "中", "level": "理解", "stem": "兩塊布樣在 D65 對色燈箱下看起來完全相同，拿到店內鎢絲燈（A 光源）下卻明顯不同。下列解釋與處置何者最恰當？", "opts": ["布料色牢度不足，在鎢絲燈的熱度下褪色；應先做日曬色牢度測試", "觀察者視角不同所致；改以 10° 觀察者計算，就能在各光源下都等色", "兩者光譜反射率不同，屬於同色異譜；應在 D65、A 等多種光源下對色", "兩塊布的光澤不同；改用 SPEX 模式量測並以 D65 數據為準即可"], "explain": "不同光譜反射率的兩個樣本，可能在某一光源與觀察者條件下等色，換光源就不等色，這就是條件等色。品管上要用多光源對色或比對光譜曲線。", "trap": "色牢度、觀察者視角與光澤都是真實概念，但都不能解釋「換光源才不等色」。", "src": "科目三指引 1.3（第 2-12 頁）", "fam": "L13-2009", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2010", "codes": ["L13103", "L13102"], "diff": "中", "level": "應用", "stem": "某色光以分光輻射儀量得三刺激值 X = 30、Y = 40、Z = 30（以 cd/m² 為單位換算）。下列敘述何者正確？", "opts": ["色度座標 (x, y) = (0.30, 0.40)，亮度為 100 cd/m²", "色度座標 (x, y) = (0.30, 0.40)，亮度為 40 cd/m²", "色度座標 (x, y) = (0.43, 0.57)，亮度為 40 cd/m²", "色度座標 (x, y) = (30, 40)，亮度無法得知"], "explain": "x = X/(X+Y+Z) = 30/100 = 0.30，y = 40/100 = 0.40。y̅ 色匹配函數等同 V(λ)，所以 Y 代表亮度，為 40 cd/m²。", "trap": "把 X+Y+Z 當亮度，或只用 X、Y 兩項計算比值（0.43、0.57），都是常見錯誤。", "src": "科目三指引 1.3（第 2-15～2-17 頁）", "fam": "xy", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2011", "codes": ["L13105", "L13103"], "diff": "中", "level": "應用", "stem": "標準色 CIELAB = (50, 10, 10)，樣品 = (52, 13, 14)。下列何者正確？", "opts": ["ΔE*ab ≈ 5.4；樣品比標準偏亮、偏紅、偏黃", "ΔE*ab ≈ 5.4；樣品比標準偏暗、偏綠、偏藍", "ΔE*ab = 9；樣品比標準偏亮、偏紅、偏黃", "ΔE*ab = 29；樣品比標準偏亮、偏綠、偏黃"], "explain": "ΔL* = +2（偏亮）、Δa* = +3（偏紅）、Δb* = +4（偏黃）；ΔE*ab = √(4+9+16) = √29 ≈ 5.4。", "trap": "9 是把三個差值直接相加；29 是忘了開根號；方向題常把 +a*、+b* 的意義顛倒。", "src": "科目三指引 1.5（第 2-25 頁）；科目二指引 1.2", "fam": "deltaE", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2012", "codes": ["L13104", "L13207"], "diff": "中", "level": "理解", "stem": "以 d/8° 幾何條件量測一塊高光澤汽車烤漆，分別用 SPIN 與 SPEX 模式。下列敘述何者正確？", "opts": ["霧面樣本兩模式差異最大；因為霧面散射強，SPIN 會多量入大量反光", "SPEX 包含鏡面反射成分；因此高光澤樣本以 SPEX 量得的 L* 通常較高", "45°/0° 幾何條件與 SPIN 相同，會把鏡面反射一併量入", "高光澤樣本兩模式差異明顯；SPEX 排除鏡面反射，量得的 L* 通常較低"], "explain": "SPIN = specular included，SPEX = specular excluded。光澤越高，鏡面反射成分越多，兩模式差異越大；排除反光後反射量較少，L* 較低。45°/0° 本身就不含鏡面反射。", "trap": "考 SPIN／SPEX 的縮寫意義，以及材質光澤與量測幾何的關係。", "src": "科目三指引 2.1（第 2-35～2-36 頁）", "fam": "spex", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2013", "codes": ["L13204", "L13101"], "diff": "中", "level": "應用", "stem": "在鎢絲燈下拍攝的影像，整體平均 RGB = (150, 100, 60)。若用「灰色世界法」並以 G 平均值為基準做白平衡，下列何者正確？", "opts": ["R 增益約 1.5、B 增益約 0.6，修正低色溫光源造成的偏藍", "三通道增益都是 1，因為灰色世界法調整的是整體亮度", "R 增益約 0.67、B 增益約 1.67，修正偏黃紅", "以影像中最亮的點當作白色，再依該點計算三通道增益"], "explain": "灰色世界法假設影像平均應為灰：R′ = R × (Ḡ/R̄) = R × 100/150 ≈ 0.67R；B′ = B × 100/60 ≈ 1.67B。低色溫光源偏黃紅，所以要壓 R、拉 B。", "trap": "以最亮點當白是「最大 RGB 值法」；倒數方向弄反會得到 1.5 與 0.6。", "src": "科目三指引 2.3（第 2-44～2-45 頁）", "fam": "wb", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2014", "codes": ["L13305", "L13205"], "diff": "中", "level": "應用", "stem": "一批以 Adobe RGB 拍攝、含大量鮮豔自然風景的照片要轉成銅版紙 CMYK 印刷，許多顏色超出印刷色域。一般建議選用哪一種演色意圖？", "opts": ["飽和度式（saturation）：優先保持鮮豔度，適合照片", "絕對色度式（absolute colorimetric）：色域外顏色不會被裁切", "演色意圖只影響色域內的顏色，選哪一種都一樣", "感應式（perceptual）：整體壓縮色域，保持色彩間的相對關係與階調"], "explain": "自然影像轉到較小的色域時，感應式會整體調整，避免色域外的顏色被裁切成一片、失去層次。飽和度式適合商業圖表；色度式會裁切色域外顏色。", "trap": "「照片很鮮豔，所以用飽和度式」是常見直覺錯誤。實務上也常用相對色度式搭配黑點補償，可在解析中延伸討論。", "src": "科目一指引 2.6（第 2-36 頁）；科目二指引 2.4", "fam": "intent", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "L13-2015", "codes": ["L13203", "L13302"], "diff": "中", "level": "應用", "stem": "設計師要為一般 sRGB 網頁與影像工作「校準」螢幕。下列哪組目標設定最合適？", "opts": ["亮度約 120 cd/m²、白點 D65、gamma 2.2", "亮度約 120 cd/m²、白點 D50、gamma 1.8，與印刷對色一致", "亮度調到最大、白點 9300 K、gamma 1.0", "不需設定目標，安裝 ICC 描述檔就等於完成校準"], "explain": "sRGB 規格採 D65 白點與約 2.2 的 gamma，一般編修環境亮度約 80–120 cd/m²。校準是把裝置調回標準狀態，描述檔是之後特性描述的產物。", "trap": "D50／1.8 是印刷軟打樣與舊 Mac 的設定，不符 sRGB 規格；最後一個選項混淆了「校準」與「特性描述」。", "src": "徐明景簡報（3C 之校準）；科目三指引 2.3", "fam": "L13-2015", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2016", "codes": ["L13201", "L13203", "L13205"], "diff": "中", "level": "理解", "stem": "比較 sRGB 顯示器與一般平版印刷（塗佈紙）的色域，下列敘述何者正確？", "opts": ["印刷色域完全落在 sRGB 之內，因為螢幕色光比油墨鮮豔", "兩者互不完全涵蓋；印刷在青綠區可超出 sRGB", "sRGB 色域完全落在印刷色域之內，因為印刷有四色、螢幕是三色", "印刷色域主要由油墨決定，紙張的白度和吸墨性影響很小"], "explain": "顯示器色域在 xy 圖上是三角形，印刷是多邊形，兩者交錯。青綠區印刷較大，所以出版流程偏好色域較大的 Adobe RGB。紙張的白度與吸墨性也會影響印刷色域。", "trap": "「螢幕比較鮮豔，所以一定包含印刷」是學生最常見的直覺。", "src": "科目三指引 2.3（第 2-48 頁）；科目二指引 2.4", "fam": "L13-2016", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2017", "codes": ["L13105", "L13206", "L13202"], "diff": "難", "level": "分析", "stem": "紡織廠的兩批布：深藍布與淺灰布相對於各自的標準，ΔE*ab 都是 1.5，但目視時淺灰布的差異明顯得多。下列處置何者最適當？", "opts": ["改用 CIEDE2000 並取 (kL, kC, kH) = (2, 1, 1)，再於標準燈箱下目視確認", "改用 CIEDE2000 並取 (kL, kC, kH) = (1, 1, 1)，因為紡織品對明度差最敏感，再於標準燈箱下目視確認", "ΔE*ab 相同代表視覺差異相同，兩批都依同一允差直接放行", "改用 xy 色度差判定，因為 xy 色度圖比 CIELAB 更均勻"], "explain": "CIELAB 並不完全均勻，ΔE*ab 在高彩度區會高估色差、在低彩度區相對低估，所以同為 1.5，灰布的差異看起來更明顯。CIEDE2000 以 S_L、S_C、S_H 依色區調整權重來修正這個問題；(2, 1, 1) 則是紡織業考量布面紋理、放寬明度差的慣用參數。數值之外，仍要在 D65、約 1000 lx、中灰背景下目視確認。", "trap": "kL = 2 的意義是「降低明度差的權重」；xy 是最不均勻的色度圖，是反向誘答。", "src": "科目三指引 2.2（第 2-39～2-40 頁）；科目二指引 2.1", "fam": "kL", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115考前模擬v1", "diag": false, "ans": "A"}, {"id": "L13-2018", "codes": ["L13302", "L13303", "L13305"], "diff": "難", "level": "分析", "stem": "攝影師交來嵌入 Adobe RGB 描述檔的商品照，設計師的 Photoshop 工作空間預設為 sRGB，印刷廠指定 ISO Coated Fogra39。下列流程何者最正確？", "opts": ["開檔時捨棄嵌入描述檔並「指定」為 sRGB，統一工作空間後再「轉換」為 Fogra39 送印", "保留嵌入描述檔編修，輸出前以「指定描述檔」標成 Fogra39，數值不變最安全", "保留嵌入描述檔編修，輸出前以「轉換為描述檔」轉到 Fogra39 並搭配軟式打樣", "把 RGB 數值依 C = 255 − R 的方式換算成 CMYK 後送印"], "explain": "「指定」只改變數值的解讀，同一組數值會看起來不同；「轉換」才會透過 PCS 把數值換成目標裝置的數值，讓外觀盡量一致。嵌入描述檔要保留，輸出時再轉換。", "trap": "捨棄嵌入描述檔再「指定」sRGB，會讓 Adobe RGB 數值被誤讀而失真；「指定」只改解讀不換數值。最後一個選項是沒有色彩管理的公式換算。", "src": "徐明景簡報（Photoshop 實務應用）；科目二指引 2.4", "fam": "assign", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "C"}, {"id": "L13-2019", "codes": ["L13101", "L13102", "L13202"], "diff": "難", "level": "應用", "stem": "對色桌只有一盞點光源，距檯面 2 m 時照度為 250 lx。要達到 CIE 建議的目視色差評估條件，下列調整何者正確？", "opts": ["燈移到距檯面 0.5 m（約 1000 lx），用約 6500 K 高演色光源與 L*≈50 中灰背景", "燈移到距檯面 1 m（約 1000 lx），用約 6500 K 高演色光源與 L*≈50 中灰背景", "燈移到距檯面 1.41 m（約 1000 lx），用約 6500 K 高演色光源與 L*≈50 中灰背景", "燈移到距檯面 1 m（約 1000 lx），改用 2700 K 暖白光與白色背景以減少疲勞"], "explain": "照度與距離平方成反比：2 m→1 m，照度變為 4 倍，250 × 4 = 1000 lx。CIE 建議的色差觀看條件為 D65、約 1000 lx、L*≈50 中灰背景。", "trap": "0.5 m 是以線性反比誤算（實際約 4000 lx）；1.41 m 只會得到 500 lx；2700 K 與白色背景都不符 CIE 建議條件。", "src": "科目三指引 1.1（第 2-5 頁）、2.2（第 2-40 頁）", "fam": "viewcond", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115考前模擬v1", "diag": false, "ans": "B"}, {"id": "L13-2020", "codes": ["L13304", "L13204", "L13105"], "diff": "難", "level": "分析", "stem": "電商攝影棚要建立相機色彩校正流程，讓商品照在 sRGB 螢幕上的顏色準確。下列做法何者最合理？", "opts": ["在標準照明下拍攝 ECI2002 導表，以 RAW 建立相機描述檔轉到 sRGB，再以各色塊的 RGB 數值差評估", "在標準照明下拍攝 ISO 12233 導表，以 RAW 建立相機描述檔，再以 ΔE 評估", "直接使用 JPEG 與自動白平衡，再以人眼在螢幕上覺得好看為準", "在標準照明下拍攝 ColorChecker 24 色導表，以 RAW 建立校正矩陣轉到 sRGB，再以 CIELAB ΔE 評估"], "explain": "相機色彩校正的標準導表是 ColorChecker（24 色或 SG）；ECI2002 是 CMYK 印刷導表，ISO 12233 用於解像力。評估要用裝置無關的 ΔE，不能用裝置相關的 RGB 差值。", "trap": "三種導表名稱的錯置，加上用 RGB 差值評估，檢查學生是否分得清裝置相關與裝置無關。", "src": "科目三指引 2.3（第 2-42、2-45 頁）", "fam": "L13-2020", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115考前模擬v1", "diag": false, "ans": "D"}, {"id": "D-01", "codes": ["L11102"], "dom": "D1", "diff": "易", "level": "知識", "stem": "一般所稱的「紅綠色盲」（第 1、2 型色覺異常），主要原因是？", "opts": ["S 錐狀細胞缺乏，使紅與綠的訊號無法區分", "桿狀細胞缺乏或功能異常", "L 或 M 錐狀細胞缺乏或異常", "大腦視覺皮質的色彩處理區受損"], "explain": "第 1 型（protan）缺 L、第 2 型（deutan）缺 M，都會混淆紅與綠；第 3 型（tritan）缺 S，混淆藍與黃，比例很少。", "trap": "S 錐細胞對應第 3 型；中樞性色盲確實存在但不是主因。", "src": "科目一指引 1.2（第 2-8 頁）", "fam": "cvd", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-02", "codes": ["L11106"], "dom": "D3", "diff": "易", "level": "理解", "stem": "色料三原色中，青（C）與洋紅（M）等量混合，理論上會得到什麼顏色？", "opts": ["紅", "綠", "黑", "藍"], "explain": "青吸收紅光、洋紅吸收綠光，剩下藍光，所以 C + M = 藍。", "trap": "M + Y = 紅、C + Y = 綠、三色相加 = 黑，三個誘答都是減法混色的其他組合。", "src": "科目一指引 1.6（第 2-23 頁）", "fam": "D-02", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-03", "codes": ["L11105"], "dom": "D2", "diff": "易", "level": "理解", "stem": "NCS 色彩標記 S 2030-Y70R，下列解讀何者正確？", "opts": ["含白度 50%；色相由 30% 黃與 70% 紅組成", "含白度 50%；色相由 70% 黃與 30% 紅組成", "含白度 30%；色相由 30% 黃與 70% 紅組成", "含黑度 30%、彩度 20%"], "explain": "20 = 含黑度、30 = 彩度，含白度 = 100 − 20 − 30 = 50。Y70R 表示從黃往紅走 70%，即 30% 黃、70% 紅。", "trap": "Y70R 的百分比是指「後面那個主色」，最常被讀反。", "src": "科目一指引 1.5；科目二指引 1.2（第 2-10～2-11 頁）", "fam": "ncs", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-04", "codes": ["L11303"], "dom": "D4", "diff": "易", "level": "理解", "stem": "同一個綠色被極細的紅色線條或藍色線條切割後，看起來分別偏紅或偏藍。這是哪一種現象？", "opts": ["同時對比", "色彩同化", "繼時對比", "色彩恆常性"], "explain": "色塊被切成極細小面積時，鄰近色會互相趨近，這是同化；面積大時則會出現相反的同時對比。", "trap": "同時對比與同化效果方向相反，關鍵在面積大小。", "src": "科目一指引 3.3（第 2-51 頁）", "fam": "assim", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-05", "codes": ["L13103"], "dom": "D6", "diff": "易", "level": "知識", "stem": "CIELAB 色彩空間中，−b* 方向代表哪一種色彩傾向？", "opts": ["黃", "綠", "紅", "藍"], "explain": "+a* 紅、−a* 綠、+b* 黃、−b* 藍，對應對立色理論的紅綠與黃藍兩軸。", "trap": "只是把四個方向交錯排列。", "src": "科目三指引 1.4（第 2-23 頁）", "fam": "D-05", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-06", "codes": ["L11201"], "dom": "D3", "diff": "易", "level": "應用", "stem": "RGB 影像每個通道以 8 bit 記錄，理論上可表現多少種顏色？", "opts": ["16,777,216", "65,536", "262,144", "1,073,741,824"], "explain": "每通道 2⁸ = 256 階，三通道為 256³ = 2²⁴ = 16,777,216 種組合。", "trap": "65,536 = 2¹⁶（把位元數看成 16）；262,144 = 2¹⁸（每通道 6 bit）；1,073,741,824 = 2³⁰（每通道 10 bit）。誘答都是位元數判讀錯誤的結果，量級相近，不能靠「看起來最大」猜答案。", "src": "科目一指引 2.1（第 2-25～2-26 頁）", "fam": "bitdepth", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-07", "codes": ["L12102"], "dom": "D2", "diff": "易", "level": "知識", "stem": "孟塞爾標記 10GY 5/10，下列解讀何者正確？", "opts": ["色相 10GY、彩度 5、明度 10", "色相 5GY、明度 10、彩度 5", "色相 10GY、明度 5、彩度 10", "色相 GY、明度 10、彩度 5"], "explain": "孟塞爾標記的順序為「色相 明度/彩度」，斜線前是明度、後是彩度。", "trap": "明度與彩度的位置對調是最常見的錯誤。", "src": "科目二指引 1.2（第 2-7 頁）；李文淵簡報", "fam": "D-07", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-08", "codes": ["L13303"], "dom": "D7", "diff": "易", "level": "理解", "stem": "為什麼不同軟體、不同作業系統，都能讀取同一個色彩描述檔（.icc／.icm）並正確轉換色彩？", "opts": ["因為所有裝置的 RGB 數值意義都相同", "描述檔採用國際色彩聯盟（ICC）制定的標準格式", "因為描述檔內容就是一張 RGB 截圖", "因為描述檔由國際照明委員會（CIE）為每台裝置分別製作"], "explain": "ICC 制定描述檔的標準格式，所以成為業界通用的色彩資訊交換標準；描述檔內容是裝置訊號與 PCS 之間的對應關係。", "trap": "CIE 制定色度學與 CIELAB，不負責描述檔格式。", "src": "徐明景簡報；科目一指引 2.6", "fam": "D-08", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-09", "codes": ["L11103", "L11104"], "dom": "D1", "diff": "中", "level": "應用", "stem": "餐廳希望營造溫暖氛圍，同時讓食物顏色看起來自然可口。下列照明規格何者最合適？", "opts": ["約 6500 K、Ra ≥ 90，因為色溫越高越溫暖", "約 2700 K、Ra 約 70，色溫比演色性重要", "約 9300 K、Ra 約 80", "約 2700–3000 K、Ra ≥ 90"], "explain": "低色溫偏黃紅，給人溫暖感；高演色性讓物體顏色忠實呈現。色溫與演色性是兩個獨立指標，要分別指定。", "trap": "「色溫越高越溫暖」是把物理溫度與心理冷暖搞混的經典錯誤。", "src": "科目一指引 1.3（第 2-10 頁）、1.4（第 2-14 頁）", "fam": "lightspec", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-10", "codes": ["L11201", "L11206"], "dom": "D7", "diff": "中", "level": "理解", "stem": "關於 sRGB 與 Adobe RGB，下列敘述何者「錯誤」？", "opts": ["兩者都定義了 RGB 訊號與 CIE 色度值的對應", "sRGB 色域較大，較適合專業商業攝影與高品質印刷", "Adobe RGB 採用更鮮豔的綠色原色", "網頁圖檔一般建議使用 sRGB"], "explain": "Adobe RGB 的色域比 sRGB 大，尤其在青綠區，因此較適合商業攝影與高品質印刷；sRGB 是網頁預設。", "trap": "把兩者的大小關係對調，同時考「何者錯誤」的閱讀。", "src": "科目一指引 2.1（第 2-27 頁）", "fam": "srgb", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-11", "codes": ["L11302", "L11403"], "dom": "D4", "diff": "中", "level": "應用", "stem": "戶外指標要在遠距離快速辨讀文字。下列文字／背景配色中，可視度最高的是？", "opts": ["黃底黑字", "紅底綠字（明度相近）", "黃底白字", "藍底黑字"], "explain": "可視度主要靠明度對比：黃底明度高、黑字明度最低，差距最大。只有色相差、沒有明度差的配色，遠距離最難辨識。", "trap": "紅底綠字色相差很大但明度相近，用來檢查學生是否知道「色相對比不等於可視度」。", "src": "科目一指引 3.2（第 2-45～2-46 頁）", "fam": "visib", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-12", "codes": ["L11402", "L12201"], "dom": "D4", "diff": "中", "level": "應用", "stem": "兩色同屬 PCCS 鮮豔色調（v），色相角相差 150°。這組配色屬於？", "opts": ["色調差配色法（tone on tone），強色相對比", "鄰近色配色法（tone in tone），弱色相對比", "色相差配色法（tonal），強色相對比", "色相差配色法（tonal），中色相對比"], "explain": "同色調、不同色相 → 色相差配色法。色相角差 ≥ 120° 為強對比、60°–120° 為中、10°–60° 為弱。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "考兩層判斷：配色法類型，以及色相對比強度的分級門檻。", "src": "科目二指引 2.3（第 2-34 頁）", "fam": "D-12", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-13", "codes": ["L12102", "L13103"], "dom": "D2", "diff": "中", "level": "應用", "stem": "某色 CIELAB = (60, 0, −40)，換成 L*C*h 表示，下列何者正確？", "opts": ["C* = 40，h = 90°，屬黃色", "C* = −40，h = 270°，屬藍色", "C* = 40，h = 270°，屬藍色", "C* = 40，h = 180°，屬綠色"], "explain": "C* = √(0² + 40²) = 40，彩度不會是負值；落在 −b* 軸上，h = 270°，為藍色。", "trap": "彩度是距離，不可能為負；把 −b* 當成 90° 是方向判斷錯誤。", "src": "科目二指引 1.2（第 2-12～2-13 頁）", "fam": "lch", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-14", "codes": ["L13305", "L11206"], "dom": "D7", "diff": "中", "level": "應用", "stem": "將簡報裡鮮豔的商業長條圖由 RGB 轉為 CMYK 輸出，希望顏色維持鮮明、色相略有偏移可以接受。應選哪一種演色意圖？", "opts": ["飽和度式（saturation）", "感應式（perceptual）", "相對色度式（relative colorimetric）", "絕對色度式（absolute colorimetric）"], "explain": "飽和度式以保持鮮豔度為優先，明度與色相可能改變，適合商業圖表。感應式適合自然影像；色度式重視色度值準確，適合打樣。", "trap": "與自然影像要用感應式的題目對照，兩種情境都答對，才代表真正理解演色意圖的適用情境。", "src": "科目一指引 2.6（第 2-36 頁）", "fam": "intent", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-15", "codes": ["L11301", "L11205", "L12201"], "dom": "D5", "diff": "中", "level": "應用", "stem": "為銀髮族保健品做色彩計畫。下列哪一種做法最符合色彩計畫的「科學化」特性？", "opts": ["依設計師對高齡者的經驗與直覺挑選主色，再交由客戶確認", "先調查目標族群的色彩意象與偏好，再據此選定主色", "直接採用今年度的國際流行色，確保包裝具有時代感", "以 3D 彩現圖中最好看的顏色作為標準色，並以色票號碼記錄"], "explain": "科學化指依客觀調查資料規劃色彩，而不是個人喜好；以色彩體系標記則對應「系統化」。", "trap": "三個誘答分別代表主觀經驗、未經驗證的趨勢，以及以彩現效果決定標準色；後者即使記下色票號碼，也只是「系統化」而不是「科學化」。", "src": "科目一指引 2.5、3.1；科目二指引 2.1（第 2-15 頁）", "fam": "plan4", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "D-16", "codes": ["L13104", "L13101"], "dom": "D6", "diff": "中", "level": "理解", "stem": "要量測（甲）螢幕白點的色度與亮度、（乙）印刷色塊的 CIELAB 值，下列儀器與校正方式的搭配何者正確？", "opts": ["甲用分光光度儀（白板校正）；乙用分光輻射儀（黑歸零）", "甲用濃度計；乙用色度計，兩者都不需事先校正", "甲用色度計（白板校正）；乙用分光輻射儀（黑歸零）", "甲用分光輻射儀（黑歸零）；乙用分光光度儀（白板校正）"], "explain": "光源色（螢幕）用分光輻射儀量 SPD，使用前做黑歸零；表面色（印刷品）用分光光度儀量光譜反射率，使用前做白板校正。", "trap": "測光源色與表面色的儀器互換，是量測單元最常見的錯誤；分光光度儀靠自帶光源量反射率，不適合量自發光的螢幕。", "src": "科目三指引 2.1（第 2-31～2-32、2-37 頁）", "fam": "calib", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-17", "codes": ["L11106", "L11207", "L13203"], "dom": "D3", "diff": "難", "level": "分析", "stem": "單晶片 DLP 投影機以色輪快速依序投射紅、綠、藍光，觀眾看到全彩影像；但有人快速轉動視線時，會在白色邊緣看到紅綠藍分離的「彩虹紋」。下列解釋何者正確？", "opts": ["DLP 屬於時序加法混色，視線快速移動時三色光落在視網膜不同位置", "DLP 屬於並置加法混色，視線快速移動時相鄰子畫素的顏色被分開看見", "DLP 屬於減法混色，色輪上的濾鏡互相重疊，使白色邊緣析出三色", "彩虹紋是白色邊緣的色彩同化現象，由相鄰色彩互相趨近而產生"], "explain": "單晶片 DLP 依時間輪流呈現 RGB，靠時間解析力不足在視覺上合成。視線快速移動時，前後出現的色光落在視網膜不同位置，就會看到分離的色邊。", "trap": "把 LCD 的並置混色、濾鏡的減法混色套到 DLP，檢查學生能否把混色原理與具體裝置對應起來。", "src": "科目一指引 1.6（第 2-22 頁）、2.7（第 2-39 頁）；陳鴻興簡報", "fam": "dlp", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "A"}, {"id": "D-18", "codes": ["L12201", "L12102", "L11205"], "dom": "D5", "diff": "難", "level": "分析", "stem": "3C 產品外殼色彩計畫完成後要交給代工廠量產。下列哪一種交付方式最能確保色彩一致？", "opts": ["提供 3D 彩現圖與螢幕上量得的 RGB 色碼，並附允許色差 ΔE 供工廠比對", "提供 CMYK 數值，因為印刷數值是跨產業通用的色彩標準", "提供色名與情境圖，例如「晨霧銀」，由工廠依經驗自行調色", "實體標準色樣＋CIELAB 值＋允許色差 ΔE，並在標準光源下目視確認"], "explain": "色彩計畫要以色票（標準色樣）與色彩標記作為生產依據，並以 CIELAB 色差訂允差。彩現圖受光影、材質影響；RGB 與 CMYK 都是裝置相關色，不能當標準色依據。", "trap": "RGB 與 CMYK 都「看起來是數字」，用來檢查學生是否真正理解裝置相關與裝置無關的差別。", "src": "科目二指引 2.1（第 2-17、2-19 頁）、2.4（第 2-40～2-41 頁）", "fam": "deliver", "type": "mc", "subj": "L12", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "D"}, {"id": "D-19", "codes": ["L13105", "L13103"], "dom": "D6", "diff": "難", "level": "分析", "stem": "品管人員比對兩個近灰色布樣，(a*, b*) 分別為 (1, 0) 與 (0, 1)，明度相同。報表上的色相角差 Δh 顯示 90°，業務擔心「色相差了 90 度，客戶一定會退貨」。下列判斷何者正確？", "opts": ["色相角差 90° 代表視覺上色相差異極大，應立即退貨", "ΔE*ab 應為 90，已遠超出允差", "ΔE*ab ≈ 1.4，全部來自色相差 ΔH*，但絕對量很小，目視差異不大，不必因 Δh 恐慌", "色相差 ΔH* 就等於 Δh，所以 ΔH* = 90"], "explain": "兩者 C* 都是 1，ΔC* = 0、ΔL* = 0，所以 ΔE*ab = √2 ≈ 1.4，全部是 ΔH*。低彩度色的色相角差可以很大，但 ΔH* 很小；品管判斷要看 ΔH* 與 ΔE，而不是 Δh。", "trap": "色相差 ΔH* 與色相角差 Δh 的區別，是官方指引特別點出的重點。", "src": "科目三指引 1.5（第 2-25 頁）", "fam": "dh", "type": "mc", "subj": "L13", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "C"}, {"id": "D-20", "codes": ["L11102", "L11302", "L12201"], "dom": "D5", "diff": "難", "level": "分析", "stem": "捷運路線圖要讓色覺異常者也能辨識各條路線。下列配色策略何者最恰當？", "opts": ["提高各路線的彩度，讓紅、綠等相鄰路線的色相差更加鮮明", "拉開相鄰路線的明度差，並加上代號、文字或線型等非色彩線索", "改用 tone in tone 配色，以統一的色調讓各路線的關係更協調", "避免紅綠並用，改以藍、紫、洋紅等其他色相區分相鄰路線"], "explain": "第 1、2 型色覺異常者難以分辨紅綠色相，但明度差仍可辨識。通用設計原則是不只靠顏色傳遞資訊，要搭配明度差與符號等冗餘線索。", "trap": "提高彩度無法解決色相混淆；tone in tone 反而縮小差異；改用藍、紫等色相仍只靠色相，藍與紫對第 1、2 型色覺異常者同樣容易混淆。", "src": "科目一指引 1.2、3.2；謝翠如簡報（通用設計）", "fam": "D-20", "type": "mc", "subj": "L11", "origin": "115考前模擬v1（診斷卷）", "diag": true, "ans": "B"}, {"id": "L11-3001", "codes": ["L11101"], "diff": "易", "level": "理解", "stem": "捷運路網圖以不同顏色區分各條路線，主要運用了色彩的哪一種功能？", "opts": ["指示性功能", "象徵性功能", "情緒影響功能", "美感功能"], "explain": "以色名或色相標記、區分類別，是指示性功能，常見於標誌與資訊視覺化。", "trap": "路線色有時也帶象徵意義，但「區分路線」的主要目的是指示。", "src": "科目一指引 1.1（第 2-2 頁）", "fam": "L11-3001", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3002", "codes": ["L11102"], "diff": "易", "level": "知識", "stem": "關於視網膜上的桿狀細胞，下列敘述何者正確？", "opts": ["主要集中在中央小窩，負責辨識細節與色彩", "分為 L、M、S 三種，各自對應不同的波長範圍", "主司暗視覺，敏感度高，但無法產生色彩訊號", "在明亮環境下主導視覺，負責感受色彩差異"], "explain": "桿狀細胞多分布於視網膜周邊，在低亮度下作用，敏感度高但沒有色彩訊號。集中於中央小窩、分三型的是錐狀細胞。", "trap": "三個誘答都是錐狀細胞的特性。", "src": "科目一指引 1.2（第 2-5～2-6 頁）", "fam": "rodcone", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3003", "codes": ["L11102", "L11303"], "diff": "中", "level": "理解", "stem": "凝視紅色圖形 30 秒後轉看白紙，會看到青綠色的殘像。下列哪一個理論最能解釋這個現象？", "opts": ["三色論：L 錐狀細胞數量不足，使白紙的紅光成分感覺偏弱", "色彩同化：殘留的紅色與白紙互相趨近而變色", "加法混色：紅色殘像與白紙的白光混合成青綠色", "對立色理論：紅—綠通道被單向刺激後產生反向反應"], "explain": "三色論說明錐狀細胞接收訊號，對立色理論說明後續處理成紅綠、黃藍、明暗通道。補色殘像是對立通道疲勞後的反向反應，三色論無法解釋。", "trap": "指引明確指出三色論無法解釋後像，這是兩理論分工的核心考點。", "src": "科目一指引 1.2（第 2-7 頁）、3.3", "fam": "after", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3004", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "博物館不能用紫外線燈或紅外線加熱燈來讓觀眾看清楚展品的顏色，最主要的原因是？", "opts": ["兩者的色溫都太低，照射下物體會偏紅而失真", "兩者的波長都落在人眼可見光範圍之外", "兩者的演色指數都太高，使物體顏色過度鮮豔", "兩者都屬於線狀光譜，演色性因此明顯偏低"], "explain": "紫外線比紫光短、紅外線比紅光長，人眼無法感應，所以不能提供色彩感覺。（此外紫外線與熱也可能傷害展品。）", "trap": "色溫、演色指數、光譜型態都是描述可見光源的指標；紫外線與紅外線根本不在可見光範圍內，套用這些指標並不成立。", "src": "科目一指引 1.3；科目三指引 1.1", "fam": "L11-3004", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3005", "codes": ["L11103", "L11104"], "diff": "中", "level": "應用", "stem": "某生鮮賣場在肉品區使用偏紅光譜的特殊燈具，讓肉看起來更鮮紅。從色彩學角度，下列判斷何者正確？", "opts": ["肉看起來更鮮豔飽和，表示這種燈的演色指數 Ra 較高", "燈的色溫若接近 6500 K，演色性便會良好", "光源光譜主要影響物體的亮度，對物體色的影響不大", "這種燈的演色性並不忠實，物體色偏離日光下的樣貌"], "explain": "演色性指光源忠實呈現物體顏色的能力，以接近日光的參考光源為準。刻意加強某段光譜讓物體更鮮豔，反而偏離參考，Ra 不一定高。色溫與演色性是兩個獨立指標。", "trap": "「更鮮豔＝演色性更好」是最常見的誤解；科目三指引的例題也考過。", "src": "科目一指引 1.4（第 2-14 頁）；科目三指引 1.5 例題", "fam": "cri", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3006", "codes": ["L11104"], "diff": "易", "level": "理解", "stem": "在白光照射下，一個紅色物體主要吸收了哪些色光？", "opts": ["綠光與藍光", "紅光", "紅光與綠光", "所有色光都等量吸收"], "explain": "紅色物體反射紅光、吸收綠光與藍光，進入眼睛的剩餘光線形成紅色感覺。", "trap": "把「看到的顏色」誤當成「吸收的顏色」。", "src": "科目一指引 1.4（第 2-13 頁）", "fam": "L11-3006", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3007", "codes": ["L11104", "L11103"], "diff": "中", "level": "應用", "stem": "在只有純藍色光照明的展場中，一顆紅蘋果看起來最可能是什麼樣子？", "opts": ["依然是紅色，因為色彩恆常性", "變成紫色，因為紅與藍混合", "很暗，接近黑色", "變成藍色，因為反射了藍光"], "explain": "紅蘋果主要反射長波長的紅光；純藍光中幾乎沒有紅光可反射，藍光又大多被吸收，所以看起來很暗。物體色取決於光源光譜與物體反射特性的共同作用。", "trap": "「變紫色」是把加法混色誤用到光源與物體的關係上；色彩恆常性無法憑空產生光源中沒有的紅光；紅蘋果吸收大部分藍光，也不會變藍。", "src": "科目一指引 1.4", "fam": "L11-3007", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3008", "codes": ["L11104"], "diff": "易", "level": "理解", "stem": "同一件衣服在店內與戶外看起來顏色不同。以色彩形成的三要素（光、物體、視覺系統）來解釋，主要改變的是哪一個要素？", "opts": ["物體：衣服的材質改變了", "光：照明光源的光譜不同", "視覺系統：觀看者換了一個人", "三要素都沒有改變，只是心理作用"], "explain": "色彩由光源、物體、視覺系統共同形成。衣服與觀看者沒變，改變的是照明光源的光譜，進入眼睛的光也就不同。", "trap": "", "src": "科目一指引 1.4（第 2-13 頁）", "fam": "L11-3008", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3009", "codes": ["L11105"], "diff": "易", "level": "知識", "stem": "PCCS 色彩體系中的「色調」（tone）綜合了哪兩個屬性？", "opts": ["色相與明度", "色相與彩度", "含黑度與含白度", "明度與彩度"], "explain": "PCCS 以「色相＋色調」表示色彩，色調把明度與彩度合為一個概念，例如鮮豔（v）、淺（lt）、深（dp），便於設計溝通。", "trap": "含黑度、含白度是 NCS 的屬性。", "src": "科目一指引 1.5（第 2-19 頁）；科目二指引 1.1", "fam": "pccs", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3010", "codes": ["L11105", "L12102"], "diff": "中", "level": "理解", "stem": "比較孟塞爾與 NCS 兩個色彩體系，下列敘述何者「錯誤」？", "opts": ["孟塞爾以明度與彩度兩軸定位同色相的色彩", "NCS 以含白度、含黑度與彩度定位同色相的色彩，三者總和為 100", "兩者都以紅、黃、綠、藍、紫五個主色構成色相環", "NCS 依據對立色理論，以紅、黃、綠、藍四色構成色相環"], "explain": "孟塞爾色相環有 R、Y、G、B、P 五個主色；NCS 依心理四原色只有 R、Y、G、B 四色。", "trap": "把孟塞爾的五主色套到 NCS 上，考兩體系的根本差異。", "src": "科目一指引 1.5；科目二指引 1.2（第 2-10 頁）", "fam": "L11-3010", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3011", "codes": ["L11106"], "diff": "易", "level": "理解", "stem": "下列哪一個例子屬於「並置加法混色」？", "opts": ["印象派點描畫與馬賽克磁磚", "兩層彩色濾鏡疊在一起", "兩種顏料在調色盤上混合", "快速旋轉的雙色陀螺"], "explain": "並置混色是極小面積的色點並排，超出眼睛空間解析力而混合，例如點描與馬賽克。濾鏡疊合與顏料混合是減法混色；旋轉陀螺是時序混色。印刷網點則是並置與疊印（減法）混合的結果。", "trap": "三個誘答分別對應減法混色與時序混色。", "src": "科目一指引 1.6（第 2-22 頁）", "fam": "L11-3011", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3012", "codes": ["L11106", "L11201"], "diff": "中", "level": "理解", "stem": "在螢幕上把紅光與綠光等量混合會看到黃色；但在調色盤上把紅色與綠色顏料等量混合，結果最可能是？", "opts": ["黃色", "暗濁的灰褐色", "白色", "比原來更亮的橙色"], "explain": "螢幕是加法混色，紅光＋綠光＝黃。顏料是減法混色，紅與綠近似互補，混合後吸收大部分光，得到暗色。", "trap": "這是官方指引的例題概念，用來確認學生分得清加法與減法混色的情境。", "src": "科目一指引 1.6（第 2-24 頁）", "fam": "L11-3012", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3013", "codes": ["L11201"], "diff": "易", "level": "理解", "stem": "在繪圖軟體的 HSB 選色器中，只拖動 S（Saturation）滑桿，顏色會怎麼變化？", "opts": ["色相改變，鮮豔程度不變", "色相不變，鮮豔程度改變", "只有明暗改變", "顏色變成 CMYK 色彩"], "explain": "HSB 以色相（H）、飽和度（S）、亮度（B）模擬知覺屬性；只調 S 時色相固定，顏色由灰往鮮豔變化。", "trap": "", "src": "科目一指引 2.1、2.4", "fam": "L11-3013", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3014", "codes": ["L11202", "L11204"], "diff": "中", "level": "應用", "stem": "攝影常用的「18% 灰卡」反射率只有 18%，卻被視為中間灰。依 CIELAB 明度公式 L* ＝ 116 (Y/Yn)^(1/3) − 16，它的 L* 約為多少？", "opts": ["約 50", "約 18", "約 82", "約 9"], "explain": "(0.18)^(1/3) ≈ 0.565，116 × 0.565 − 16 ≈ 49.5。人眼的明度感覺與亮度呈非線性關係，所以 18% 反射率在感覺上約在中間。", "trap": "18 是直接把反射率當明度，正是心理物理學要修正的線性直覺。", "src": "科目一指引 2.2（第 2-28 頁）", "fam": "L11-3014", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3015", "codes": ["L11203"], "diff": "易", "level": "理解", "stem": "評估色彩複製品質時，下列敘述何者正確？", "opts": ["應以標準光源下的目視比對為準，色差數值無法反映實際觀感", "應以 CIE 色差數值為準，用途與觀者偏好屬於主觀因素不宜納入", "原稿與複製品色差越小越好，因此依偏好所做的調整都會降低品質", "可用 CIE 色差公式客觀評估，也可依用途與偏好主觀評估"], "explain": "色彩複製品質可以客觀（色差公式）或主觀（使用目的、觀者偏好、客戶需求）評估，兩者常並用。", "trap": "前兩個誘答各把主觀或客觀評估當成唯一標準；第三個忽略了依用途或偏好刻意調整（如記憶色）也可以是好的複製。", "src": "科目一指引 2.3（第 2-30 頁）", "fam": "repro", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3016", "codes": ["L11206"], "diff": "易", "level": "應用", "stem": "客戶要求「這個品牌色在任何螢幕與印刷品上都要一致」。在規格書中記錄標準色時，最應該使用哪一種數值？", "opts": ["螢幕上的 RGB 色碼", "印刷用的 CMYK 百分比", "CIELAB 值", "網頁的 HEX 色碼"], "explain": "RGB、HEX、CMYK 都是裝置相關的控制訊號，同樣的數值在不同裝置上顏色不同。CIELAB 以人眼視覺定義，是裝置無關的描述方式。", "trap": "HEX 只是 RGB 的另一種寫法。", "src": "科目一指引 2.6（第 2-35 頁）", "fam": "L11-3016", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3017", "codes": ["L11207", "L11106"], "diff": "中", "level": "理解", "stem": "比較 OLED 與 LCD 顯示器，下列敘述何者正確？", "opts": ["LCD 自發光，OLED 需要背光；兩者都以 RGB 子畫素並置混色", "OLED 自發光，不需背光；兩者都以 RGB 子畫素並置混色", "OLED 自發光，不需背光；但 OLED 以 CMY 減法混色呈現全彩", "兩者都需要背光模組；LCD 以時序混色、OLED 以並置混色"], "explain": "OLED 的有機發光層通電後自行發光，可省去背光與部分濾光片，因此更輕薄。兩者都以 RGB 子畫素並置的加法混色呈現全彩。", "trap": "考「自發光」與「混色方式」兩個面向。", "src": "科目一指引 2.7（第 2-38～2-39 頁）", "fam": "dlp", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3018", "codes": ["L11301"], "diff": "易", "level": "理解", "stem": "從日光燈下走到夕陽下，白紙看起來仍然是白色。這主要是哪一種現象？", "opts": ["色彩恆常性", "色彩同化", "色彩同時對比", "條件等色"], "explain": "色彩恆常性指視覺系統會適應或補償光源變化，維持穩定的物體色感覺；相機的白平衡是在模仿這個機制。", "trap": "條件等色是兩個光譜不同的物體在某光源下等色，與單一物體跨光源的穩定感不同。", "src": "科目一指引 3.1（第 2-41 頁）", "fam": "L11-3018", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3019", "codes": ["L11302", "L11303"], "diff": "中", "level": "應用", "stem": "海報上明度相近的高彩度紅字放在綠底上，邊界顯得模糊、閃爍。下列哪一種改善方式最有效？", "opts": ["把紅字的彩度再提高，讓文字從綠底中更加突顯", "把綠底換成同明度的藍色，避開紅綠互補的強烈對比", "把字體縮小並加密，讓同化效果中和邊界的閃爍", "在紅字外加黑色或白色描邊，並拉開字與底的明度差"], "explain": "中高彩度、明度相近的兩色相鄰會產生色滲，以中性色隔開可降低；拉開明度差則能提高可視度。", "trap": "提高彩度或換成同明度的另一色相，都無法解決明度差不足的問題。", "src": "科目一指引 3.2、3.3（第 2-49 頁）", "fam": "bleed", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3020", "codes": ["L11404", "L11401"], "diff": "中", "level": "應用", "stem": "一個文創品牌希望包裝呈現「沉穩、復古、樸素」的感覺。依「以彩度為主的配色」原則，下列哪一種方向最合適？", "opts": ["選用高彩度的同彩度組合", "選用無彩色搭配高彩度螢光色", "選用中低彩度的同彩度組合", "選用互補色、高彩度強對比"], "explain": "同彩度配色中，高彩度組呈現活潑年輕感，中低彩度組則偏向穩重、成熟、樸素、復古。", "trap": "高彩度與強對比會傳達相反的意象。", "src": "科目一指引 4.4（第 2-57 頁）", "fam": "L11-3020", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3021", "codes": ["L11403", "L11302", "L11102"], "diff": "難", "level": "分析", "stem": "一份資訊圖表以「綠→黃→紅」表示風險高低，但常被黑白影印，讀者中也有紅綠色覺異常者。下列修正方式何者最恰當？", "opts": ["保持綠黃紅配色，但提高各色的飽和度讓差異更明顯", "改用明度相同的紅、綠、藍三色，以色相差區分等級", "改用由淺到深、明度單向漸變的色階", "改用七色彩虹色階，以更多色相細分風險等級"], "explain": "明度差在灰階列印與紅綠色覺異常時都仍然存在；單向明度漸變也最符合「數值越高、越深」的直覺。只靠色相差的色階兩種情境都會失效。", "trap": "飽和度與色相差在灰階列印時都會消失；彩虹色階的明度不單調，是資訊視覺化常見的錯誤。", "src": "科目一指引 1.2、3.2、4.3；謝翠如簡報", "fam": "L11-3021", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-3022", "codes": ["L11303", "L11205"], "diff": "難", "level": "分析", "stem": "服飾品牌開發細格紋布料：小色樣上的格紋與底色看起來分明，但做成整件外套遠看時，整體色調明顯偏向格紋線色。從色彩計畫角度，下列判斷與做法何者最恰當？", "opts": ["這是色彩同化；應以全尺寸樣品在實際觀看距離確認", "這是同時對比；應把格紋線加粗，讓線色與底色的差異更明顯", "這是條件等色；應改在標準光源下重新量測布料色值", "這是視覺疲勞；小色樣已確認過，量產時維持原配方即可"], "explain": "細小面積的色彩會與鄰近色互相趨近（同化），遠看時線條在視網膜上更細，效果更強。指引也提醒最終色彩要在全尺寸物體上確認。", "trap": "同時對比與同化效果相反，關鍵在面積與觀看距離；條件等色涉及光源變化，與面積大小無關。", "src": "科目一指引 3.3（第 2-51 頁）；科目二指引 2.1 注意事項", "fam": "L11-3022", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3023", "codes": ["L11206", "L11203", "L11204"], "diff": "難", "level": "分析", "stem": "設計師在 sRGB 螢幕上調出一個很鮮豔的翠綠色做為主視覺，印刷後卻明顯變暗變濁。下列解釋與做法何者最恰當？", "opts": ["印刷廠油墨品質不良；應更換印刷廠，並要求使用高濃度油墨", "該色超出 CMYK 色域；應以軟式打樣與印刷色票或專色確認", "螢幕亮度設得太低；應先調亮螢幕，再依新的畫面重新調色", "RGB 轉 CMYK 時數值換算錯誤；應把 RGB 數值直接填入 CMYK 欄位"], "explain": "RGB 與 CMYK 色域互不完全涵蓋，鮮豔綠色常在印刷色域外。設計階段就要用軟式打樣與實體色票確認，必要時改用專色。", "trap": "換廠或調螢幕都沒有處理色域與色彩管理的根本問題。", "src": "科目一指引 2.6；科目二指引 2.4（第 2-39～2-40 頁）", "fam": "L11-3023", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-3024", "codes": ["L11402"], "diff": "易", "level": "理解", "stem": "以色相為主的配色中，選用互補色相（色相差很大）的搭配，通常會產生什麼效果？", "opts": ["協調柔和", "單純一致", "沉穩樸素", "對比強烈"], "explain": "色相差大（如補色）產生對比效果；選鄰近色相則產生協調效果。", "trap": "協調是鄰近色相的效果。", "src": "科目一指引 4.2（第 2-55 頁）", "fam": "L11-3024", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-3025", "codes": ["L11403"], "diff": "易", "level": "理解", "stem": "選擇「不同色相、相同明度」的色彩組合，在高明度組與低明度組分別會給人什麼感覺？", "opts": ["高明度組輕快，低明度組沉穩", "高明度組沉穩，低明度組輕快", "兩者都很刺激", "明度與感覺無關"], "explain": "依指引，同明度配色中，高明度組感覺輕快，低明度組感覺沉穩。", "trap": "與彩度配色（活潑 vs 樸素）的效果互相對照。", "src": "科目一指引 4.3（第 2-56 頁）", "fam": "L11-3025", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-3026", "codes": ["L11201", "L11106", "L11207"], "diff": "難", "level": "分析", "stem": "一張天空藍漸層的海報，在一般 8-bit 螢幕上出現一圈圈明顯的「色帶」（banding）。下列解釋與改善方式何者最恰當？", "opts": ["螢幕的色溫太高；把白點改成 5000 K，相鄰色階就不再分明", "sRGB 色域太小；改用 CMYK 或廣色域的檔案，相鄰色階的過渡就會平順", "色階數不足以呈現平緩漸層；可提高色彩深度或加入 dithering", "這是色彩同化，相鄰色帶互相趨近；改成水平方向的漸層即可"], "explain": "8-bit 每通道只有 256 階，緩慢的大面積漸層會出現可辨識的階差。提高位元深度可增加階數；dithering 用細小雜點讓眼睛把相鄰階混合（並置混色），在不增加位元數的情況下減少色帶。", "trap": "色帶是階調（色彩深度）問題，不是色溫、色域或色彩同化的問題；擴大色域而不增加位元數，色帶反而可能更明顯。", "src": "科目一指引 1.6、2.1（第 2-25～2-26 頁）、2.7", "fam": "L11-3026", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L12-3001", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["2", "5", "3", "4", "1"], "stem": "下列 5 張色票的色相與彩度相同。請依「明度」由低到高排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "這五張同色相、同彩度，只有明度不同。由低到高：色票 2（5PB 3/4）、色票 5（5PB 4/4）、色票 3（5PB 5/4）、色票 4（5PB 6/4）、色票 1（5PB 7/4）。", "trap": "只變動一個屬性，是三屬性辨識的基本題。排錯通常是中間三階相鄰兩張對調。", "src": "科目二評鑑內容 L12101；李文淵簡報", "fam": "order-L", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 7/4", "hex": "#9EAFC7"}, {"label": "2", "spec": "5PB 3/4", "hex": "#374864"}, {"label": "3", "spec": "5PB 5/4", "hex": "#6B7A94"}, {"label": "4", "spec": "5PB 6/4", "hex": "#8594AD"}, {"label": "5", "spec": "5PB 4/4", "hex": "#51617B"}]}, {"id": "L12-3002", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["5", "4", "1", "3", "2"], "stem": "下列 5 張色票的色相與彩度相同。請依「明度」由低到高排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "同為 5G、彩度 4，明度依序為 3、4、6、7、8：色票 5（5G 3/4）、色票 4（5G 4/4）、色票 1（5G 6/4）、色票 3（5G 7/4）、色票 2（5G 8/4）。", "trap": "這組明度間距不等（4 到 6 跳一階），用來檢查學生是否真的在比較明度，而不是靠均勻間距猜順序。", "src": "科目二評鑑內容 L12101", "fam": "order-L", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5G 6/4", "hex": "#6B9E85"}, {"label": "2", "spec": "5G 8/4", "hex": "#9FD4B7"}, {"label": "3", "spec": "5G 7/4", "hex": "#85B99E"}, {"label": "4", "spec": "5G 4/4", "hex": "#3B6954"}, {"label": "5", "spec": "5G 3/4", "hex": "#24503D"}]}, {"id": "L12-3003", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["5", "4", "3", "1", "2"], "stem": "下列 5 張色票的色相與明度相同。請依「彩度」由低（灰）到高（鮮豔）排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "同色相、同明度，彩度依序為 2、4、6、8、10。", "trap": "中間三階的彩度差最難分辨。", "src": "科目二評鑑內容 L12101", "fam": "order-C", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 5/8", "hex": "#B7605E"}, {"label": "2", "spec": "5R 5/10", "hex": "#C45756"}, {"label": "3", "spec": "5R 5/6", "hex": "#AA6765"}, {"label": "4", "spec": "5R 5/4", "hex": "#9B6E6C"}, {"label": "5", "spec": "5R 5/2", "hex": "#8A7573"}]}, {"id": "L12-3004", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "ans": ["3", "5", "1", "2", "4"], "stem": "下列 5 張色票的色相與明度相同。請依「彩度」由低到高排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "同為 5PB、明度 5，彩度依序為 2、4、6、8、10。", "trap": "高彩度的藍紫看起來較亮（Helmholtz–Kohlrausch 效應），學生容易把彩度變化誤判成明度變化。", "src": "科目二評鑑內容 L12101", "fam": "order-C", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 5/6", "hex": "#617BA2"}, {"label": "2", "spec": "5PB 5/8", "hex": "#547BB0"}, {"label": "3", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "4", "spec": "5PB 5/10", "hex": "#437CBD"}, {"label": "5", "spec": "5PB 5/4", "hex": "#6B7A94"}]}, {"id": "L12-3005", "codes": ["L12101", "L12102"], "diff": "中", "level": "分析", "type": "seq", "ans": ["2", "3", "4", "5", "1"], "stem": "下列 5 張色票的色相各不相同。請只依「明度」由低到高排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "明度依序：色票 2（5P 3/6）、色票 3（5Y 4/6）、色票 4（5G 5/6）、色票 5（5R 6/6）、色票 1（5PB 7/6）。", "trap": "黃色常被直覺判為最亮，但 5Y 4/6 是暗橄欖色。這題檢查能否把色相與明度分開判斷。", "src": "科目二評鑑內容 L12101；科目二指引 1.1", "fam": "light-order", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 7/6", "hex": "#94AFD6"}, {"label": "2", "spec": "5P 3/6", "hex": "#5A3B67"}, {"label": "3", "spec": "5Y 4/6", "hex": "#735E15"}, {"label": "4", "spec": "5G 5/6", "hex": "#3B8767"}, {"label": "5", "spec": "5R 6/6", "hex": "#C4827E"}]}, {"id": "L12-3006", "codes": ["L12101", "L12102"], "diff": "中", "level": "分析", "type": "seq", "ans": ["1", "5", "3", "4", "2"], "stem": "下列 5 張色票的色相與彩度不完全相同。請只依「明度」由低到高排列。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "明度依序：色票 1（5R 3/6）、色票 5（5YR 4/6）、色票 3（10B 5/6）、色票 4（5P 6/6）、色票 2（5YR 7/8）。", "trap": "兩張同為 5YR，但明度差 3 階；高彩度色因 H-K 效應看起來較亮，容易被排得太後面。", "src": "科目二評鑑內容 L12101", "fam": "light-order", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 3/6", "hex": "#743335"}, {"label": "2", "spec": "5YR 7/8", "hex": "#E69D64"}, {"label": "3", "spec": "10B 5/6", "hex": "#48809F"}, {"label": "4", "spec": "5P 6/6", "hex": "#A38AB3"}, {"label": "5", "spec": "5YR 4/6", "hex": "#88532F"}]}, {"id": "L12-3007", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["3"], "stem": "某產品色彩規格為孟塞爾 5Y 8/10。請輸入最符合的色票編號。", "explain": "5Y 8/10：色相 5Y、明度 8、彩度 10，是明亮鮮豔的黃，即 色票 3（5Y 8/10）。卡上相近的 色票 1（5Y 8/4）（彩度較低）、色票 4（5GY 8/10）（偏黃綠）、色票 2（5Y 6/8）（較暗較灰）都是誘答。", "trap": "卡上放了三張只差一個或兩個屬性的黃色。", "src": "科目二指引 1.2", "fam": "find", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5Y 8/4", "hex": "#D6C891"}, {"label": "2", "spec": "5Y 6/8", "hex": "#AD9124"}, {"label": "3", "spec": "5Y 8/10", "hex": "#E6C737"}, {"label": "4", "spec": "5GY 8/10", "hex": "#B6D544"}]}, {"id": "L12-3008", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["3"], "stem": "規格為孟塞爾 5PB 5/8。請輸入最符合的色票編號。", "explain": "5PB 明度 5 的彩度系列在卡上有 /2、/4、/6、/8、/10 五張，答案是 色票 3（5PB 5/8）。", "trap": "要在相鄰彩度階之間做選擇，是讀標記加上判斷彩度的組合。", "src": "科目二指引 1.2", "fam": "find", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 5/4", "hex": "#6B7A94"}, {"label": "2", "spec": "5PB 5/10", "hex": "#437CBD"}, {"label": "3", "spec": "5PB 5/8", "hex": "#547BB0"}, {"label": "4", "spec": "5PB 5/6", "hex": "#617BA2"}]}, {"id": "L12-3009", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "ans": ["4"], "stem": "規格為孟塞爾 5BG 6/4。請輸入最符合的色票編號。", "explain": "答案是 色票 4（5BG 6/4）。卡上還有 5BG 的其他明度階，以及 色票 1（10G 5/4）、5BG 5/2 等相近色。", "trap": "同色相相鄰明度階的辨識。", "src": "科目二指引 1.2", "fam": "find", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "10G 5/4", "hex": "#4F8475"}, {"label": "2", "spec": "5BG 5.5/4", "hex": "#56918B"}, {"label": "3", "spec": "5BG 5/4", "hex": "#4B837E"}, {"label": "4", "spec": "5BG 6/4", "hex": "#629E97"}, {"label": "5", "spec": "5BG 7/4", "hex": "#7DB9B0"}]}, {"id": "L12-3010", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["5", "4", "3"], "stem": "請從候選色票中選出三張，依序補在左端與右端之間，形成由暗到亮的等色差色階。請依序輸入三個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "兩端只有明度不同（3→7），中間應為明度 4、5、6：色票 5（5BG 4/4）、色票 4（5BG 5/4）、色票 3（5BG 6/4）。", "trap": "卡上的 色票 6（10G 5/4） 色相偏移、色票 1（5BG 5/2） 彩度降低、色票 2（5BG 5.5/4） 明度不等距，分別對應三種錯誤。", "src": "簡章能力指標：調製兩色之間的等色差色階", "fam": "grad", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5BG 5/2", "hex": "#647F7C"}, {"label": "2", "spec": "5BG 5.5/4", "hex": "#56918B"}, {"label": "3", "spec": "5BG 6/4", "hex": "#629E97"}, {"label": "4", "spec": "5BG 5/4", "hex": "#4B837E"}, {"label": "5", "spec": "5BG 4/4", "hex": "#2F6966"}, {"label": "6", "spec": "10G 5/4", "hex": "#4F8475"}], "ends": [{"label": "左端", "spec": "5BG 3/4", "hex": "#12504E"}, {"label": "右端", "spec": "5BG 7/4", "hex": "#7DB9B0"}]}, {"id": "L12-3011", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["2", "6", "5"], "stem": "請從候選色票中選出三張，依序補在左端與右端之間，形成由暗到亮的等色差色階。請依序輸入三個色票編號。【全對全錯】", "explain": "中間階為明度 4、5、6、彩度 4：色票 2（5PB 4/4）、色票 6（5PB 5/4）、色票 5（5PB 6/4）。", "trap": "卡上 5PB 明度 5 有多種彩度（/2、/6、/8、/10），選錯代表忽略了彩度要保持一致。", "src": "簡章能力指標", "fam": "grad", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "10B 5/6", "hex": "#48809F"}, {"label": "2", "spec": "5PB 4/4", "hex": "#51617B"}, {"label": "3", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "4", "spec": "5PB 5/6", "hex": "#617BA2"}, {"label": "5", "spec": "5PB 6/4", "hex": "#8594AD"}, {"label": "6", "spec": "5PB 5/4", "hex": "#6B7A94"}], "ends": [{"label": "左端", "spec": "5PB 3/4", "hex": "#374864"}, {"label": "右端", "spec": "5PB 7/4", "hex": "#9EAFC7"}]}, {"id": "L12-3012", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "ans": ["1", "6", "3"], "stem": "請從候選色票中選出三張，依序補在左端與右端之間，形成由灰到鮮豔的等色差色階。請依序輸入三個色票編號。【全對全錯】", "explain": "兩端只有彩度不同（2→10），中間應為彩度 4、6、8：色票 1（5R 5/4）、色票 6（5R 5/6）、色票 3（5R 5/8）。", "trap": "卡上的 色票 4（5R 6/6）、色票 2（5R 3/6） 彩度對但明度不同，是誘答。", "src": "簡章能力指標", "fam": "grad", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 5/4", "hex": "#9B6E6C"}, {"label": "2", "spec": "5R 3/6", "hex": "#743335"}, {"label": "3", "spec": "5R 5/8", "hex": "#B7605E"}, {"label": "4", "spec": "5R 6/6", "hex": "#C4827E"}, {"label": "5", "spec": "5R 5/12", "hex": "#D04C50"}, {"label": "6", "spec": "5R 5/6", "hex": "#AA6765"}], "ends": [{"label": "左端", "spec": "5R 5/2", "hex": "#8A7573"}, {"label": "右端", "spec": "5R 5/10", "hex": "#C45756"}]}, {"id": "L12-3013", "codes": ["L12201", "L12101"], "diff": "中", "level": "分析", "type": "code", "ans": "2413", "stem": "下列四組配色 P1～P4 分別使用了哪一種配色法？請依 P1、P2、P3、P4 的順序輸入代號：1 鄰近色配色法、2 色調差配色法、3 色相差配色法、4 無彩配有彩。（4 個代號連寫）。（本題的「同色調」指 CIELAB 的 L* 與 C* 相近。）【全對全錯】", "explain": "P1 同色相、不同色調 → 2。P2 以無彩色為主、搭配小面積黃 → 4。P3 色相相鄰、色調相近 → 1。P4 三張的 CIELAB L* 約 80、C* 約 30，色調相同、色相差大 → 3。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "P1 與 P3 都看起來協調，關鍵在色相「相同」還是「相鄰」。", "src": "科目二指引 2.3；李文淵簡報 Hue-Tone 配色原則", "fam": "L12-3013", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "groups": [{"label": "P1", "chips": [{"label": "", "spec": "5Y 9/2", "hex": "#ECE3C3"}, {"label": "", "spec": "5Y 7/6", "hex": "#C2AD5E"}, {"label": "", "spec": "5Y 4/4", "hex": "#6F5F30"}]}, {"label": "P2", "chips": [{"label": "", "spec": "N 9", "hex": "#E3E3E3"}, {"label": "", "spec": "N 3", "hex": "#474848"}, {"label": "", "spec": "5Y 8/10", "hex": "#E6C737"}]}, {"label": "P3", "chips": [{"label": "", "spec": "5Y 8/4", "hex": "#D6C891"}, {"label": "", "spec": "10YR 7/4", "hex": "#C7A97F"}, {"label": "", "spec": "5GY 8/4", "hex": "#C2CE95"}]}, {"label": "P4", "chips": [{"label": "", "spec": "5Y 8/4", "hex": "#D6C891"}, {"label": "", "spec": "LCh 80/30/270", "hex": "#A3C9FE"}, {"label": "", "spec": "LCh 80/30/350", "hex": "#F8B3D1"}]}]}, {"id": "L12-3014", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "type": "set", "ans": ["2", "3", "5"], "stem": "要以主色搭配「色相差配色法」（同色調、不同色相）。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。（本題的「同色調」指 CIELAB 的 L* 與 C* 相近。）【全對全錯】", "explain": "主色 主色（5Y 8/4） 的 CIELAB 約為 L* 81、C* 30。同色調指 L* 與 C* 相近：色票 5（LCh 80/30/270）、色票 3（LCh 80/30/350） 與主色相同，色票 2（5G 8/4）（L* 81、C* 25）也在相近範圍內，三者色相都不同。色票 6（5Y 9/2）、色票 1（5Y 7/6） 同色相，屬色調差；色票 4（10YR 7/4） 的 L* 約 71，明度差較大。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "考 tonal 的條件是「色調一致」，而不是「看起來不同色」。", "src": "科目二指引 2.3（第 2-34 頁）", "fam": "L12-3014", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5Y 7/6", "hex": "#C2AD5E"}, {"label": "2", "spec": "5G 8/4", "hex": "#9FD4B7"}, {"label": "3", "spec": "LCh 80/30/350", "hex": "#F8B3D1"}, {"label": "4", "spec": "10YR 7/4", "hex": "#C7A97F"}, {"label": "5", "spec": "LCh 80/30/270", "hex": "#A3C9FE"}, {"label": "6", "spec": "5Y 9/2", "hex": "#ECE3C3"}], "main": {"label": "主色", "spec": "5Y 8/4", "hex": "#D6C891"}}, {"id": "L12-3015", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "type": "set", "ans": ["3", "4", "6"], "stem": "要以主色搭配「色調差配色法」（同色相、不同色調）。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。【全對全錯】", "explain": "同色相 5YR 的三張：色票 4（5YR 4/6）、色票 6（5YR 8/4）、色票 3（5YR 7/8）。其餘三張色相不同。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "色票 2（10YR 7/4） 和 色票 1（5R 6/6） 色相與主色相鄰，看起來很像，屬於鄰近色配色法。", "src": "科目二指引 2.3（第 2-33 頁）", "fam": "L12-3015", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 6/6", "hex": "#C4827E"}, {"label": "2", "spec": "10YR 7/4", "hex": "#C7A97F"}, {"label": "3", "spec": "5YR 7/8", "hex": "#E69D64"}, {"label": "4", "spec": "5YR 4/6", "hex": "#88532F"}, {"label": "5", "spec": "5Y 7/6", "hex": "#C2AD5E"}, {"label": "6", "spec": "5YR 8/4", "hex": "#E9C0A2"}], "main": {"label": "主色", "spec": "5YR 6/8", "hex": "#CA834B"}}, {"id": "L12-3016", "codes": ["L12201", "L12101"], "diff": "中", "level": "理解", "type": "set", "ans": ["3", "5", "6"], "stem": "若以 CIELAB 彩度 C* ≤ 5 定義無彩色，下列色票中，哪些可以當作「無彩配有彩」中的無彩色？請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。【全對全錯】", "explain": "無彩色只有 色票 3（N 9）、色票 5（N 5）、色票 6（N 3）。孟塞爾彩度 2 的顏色，換算成 CIELAB 的 C* 約在 7–17（黃色最高），都超過 5，屬於低彩度的有彩色。", "trap": "低彩度不等於無彩色，是配色實務的常見誤解。", "src": "李文淵簡報（無彩配有彩）；科目二指引 2.3", "fam": "L12-3016", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "2", "spec": "5BG 5/2", "hex": "#647F7C"}, {"label": "3", "spec": "N 9", "hex": "#E3E3E3"}, {"label": "4", "spec": "5Y 9/2", "hex": "#ECE3C3"}, {"label": "5", "spec": "N 5", "hex": "#797979"}, {"label": "6", "spec": "N 3", "hex": "#474848"}]}, {"id": "L12-3017", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "mc", "stem": "運動飲料包裝以底色 5B 3/4 為大面積、標誌色 5R 5/12 為點綴。依孟塞爾「色彩強度與面積成反比」原則，底色與標誌色的面積比約應為？", "opts": ["1：5", "12：5", "3：5", "5：1"], "explain": "強度＝明度×彩度：底色 3×4＝12，標誌色 5×12＝60。A₁/A₂＝V₂C₂/V₁C₁＝60/12＝5，弱色面積約為強色的 5 倍。", "trap": "1：5 把反比做成正比；12：5、3：5 只比較了單一屬性。", "src": "科目二指引 2.2（第 2-21 頁）", "fam": "area", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ends": [{"label": "底色", "spec": "5B 3/4", "hex": "#154E5E"}, {"label": "標誌色", "spec": "5R 5/12", "hex": "#D04C50"}], "ans": "D"}, {"id": "L12-3018", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "mc", "stem": "一張海報以背景 5G 3/4 為大面積、重點色 5YR 7/8 為小面積。依孟塞爾面積平衡原則，背景與重點色的面積比約應為？", "opts": ["約 1：4.7", "約 4.7：1", "約 2：1", "約 7：3"], "explain": "背景強度 3×4＝12，重點色 7×8＝56。面積比＝56/12≈4.7，背景面積約為重點色的 4.7 倍。", "trap": "與上一題同概念、不同數字，用來確認不是背答案。", "src": "科目二指引 2.2", "fam": "area", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ends": [{"label": "背景", "spec": "5G 3/4", "hex": "#24503D"}, {"label": "重點色", "spec": "5YR 7/8", "hex": "#E69D64"}], "ans": "B"}, {"id": "L12-3019", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "mc", "stem": "NCS 標記 S 1060-R20B，下列解讀何者正確？", "opts": ["含黑度 10%、彩度 60%、含白度 30%；色相為 20% 紅、80% 藍", "含黑度 60%、彩度 10%；色相為 80% 紅、20% 藍", "含白度 10%、彩度 60%；色相為 20% 紅、80% 藍", "含黑度 10%、彩度 60%、含白度 30%；色相為 80% 紅、20% 藍"], "explain": "前兩碼為含黑度 10，後兩碼為彩度 60，含白度＝100−10−60＝30。R20B 表示由紅往藍走 20%，即 80% 紅、20% 藍，是帶點紫的紅。", "trap": "R20B 的百分比指向後面的主色；黑度與彩度位置也常讀反。", "src": "科目二指引 1.2（第 2-10～2-11 頁）", "fam": "ncs", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L12-3020", "codes": ["L12102", "L13103"], "diff": "中", "level": "應用", "type": "mc", "stem": "某包裝標準色為 CIELAB (65, −25, 25)。下列何者正確？", "opts": ["C* ≈ 35.4，h＝45°，屬橙色", "C*＝50，h＝135°，屬黃綠色", "C* ≈ 35.4，h＝135°，屬黃綠色", "C* ≈ 35.4，h＝225°，屬青藍色"], "explain": "C*＝√(25²+25²)≈35.4。−a* 偏綠、+b* 偏黃，位於第二象限，h＝180°−45°＝135°。", "trap": "C*＝50 是把 |a*|、|b*| 相加；45° 是忘了判斷象限。", "src": "科目二指引 1.2（第 2-12～2-13 頁）", "fam": "lch", "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L12-3021", "codes": ["L12201"], "diff": "易", "level": "應用", "type": "mc", "stem": "設計師拿到吹風機的設計目標「專業、可靠」後，立刻挑了喜歡的主色與輔色，最後才決定哪些組件要分色，結果外殼出現五種顏色、顯得雜亂。依指引的色彩設計思考流程，問題出在哪裡？", "opts": ["順序顛倒：應先設定分色區域（通常不超過 3 色），再解構設計目標選色，最後檢視整體造形", "選色前沒有先做 3D 彩現", "沒有先選定印刷用的 CMYK 數值", "應先檢視整體造形，再設定分色區域"], "explain": "指引的三階段為：設定分色區域 → 解構與建構設計目標（關鍵字對應三屬性，選主色、輔色）→ 檢視整體造形，後兩階段會反覆來回。先決定分色區域，才能控制顏色數量。", "trap": "", "src": "科目二指引 2.1（第 2-16～2-17 頁）", "fam": "planstep", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L12-3022", "codes": ["L12201", "L11205"], "diff": "中", "level": "應用", "type": "mc", "stem": "一台有五個外觀組件的吹風機要做色彩計畫，設計目標是「專業、可靠」。下列做法何者最符合指引？", "opts": ["五個組件各用一色，以色彩差異化讓使用者辨識各部位功能", "外觀控制在 3 色以內，依「專業、可靠」對應的色彩屬性選主色，再配輔色", "依今年流行色決定主色，再以「專業、可靠」的形象選低彩度輔色", "外觀控制在 3 色以內，先做 3D 彩現，再以彩現圖上的顏色作為量產標準色"], "explain": "產品外觀以不超過 3 色為原則；色彩設計要把目標關鍵字轉成色彩三屬性的選擇，而不是依個人或流行偏好。3D 彩現受光影材質影響，不能當標準色。", "trap": "「差異化」是色彩計畫特性之一，但不是每個組件都不同色；主色應由設計目標推導而非流行色；3D 彩現受光影材質影響，不能當量產標準色。", "src": "科目二指引 2.1（第 2-16～2-17 頁）", "fam": "L12-3022", "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3001", "codes": ["L13102"], "diff": "易", "level": "知識", "stem": "下列光度量與單位的對應，何者正確？", "opts": ["照度：燭光（cd）；亮度：流明每平方公尺（lm/m²）", "光通量：勒克斯（lx）；光強度：cd/m²（nit）", "照度：勒克斯（lx）；亮度：cd/m²（nit）", "光強度：流明（lm）；照度：瓦特（W）"], "explain": "光通量 lm、光強度 cd（lm/sr）、照度 lx（lm/m²）、亮度 cd/m²（nit）。", "trap": "四個光度量的單位彼此錯置；lm/m² 其實就是照度單位 lx，不是亮度。", "src": "科目三指引 1.1（第 2-5 頁）", "fam": "flux", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3002", "codes": ["L13101"], "diff": "易", "level": "理解", "stem": "要為對色燈箱挑選光源，比較鎢絲燈（連續光譜）、白光 LED（組合光譜）、雷射光源（線狀光譜）。哪一種光譜型態最不適合作為對色照明？", "opts": ["鎢絲燈的連續光譜：長波長偏多，會讓藍色物體顯得暗沉", "雷射光源的線狀光譜", "白光 LED 的組合光譜：由數個波段組合而成，缺少連續性", "三者都適合，相關色溫相同就能對色"], "explain": "線狀光譜只在一個或少數幾個波長發光，缺少其他波段，物體在該光源下的顏色會嚴重失真；對色照明需要接近日光、連續且完整的光譜。", "trap": "鎢絲燈偏紅、LED 波段不平均都是真實缺點，但兩者仍涵蓋整個可見光範圍；只有線狀光譜缺少大部分波長。", "src": "科目三指引 1.2（第 2-8、2-11～2-12 頁）", "fam": "L13-3002", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3003", "codes": ["L13103"], "diff": "易", "level": "理解", "stem": "CIE 1931（2°）與 CIE 1964（10°）標準觀察者，下列敘述何者正確？", "opts": ["10° 適用於影像等小視角，2° 適用於大面積色樣", "兩者主要差在制定年份，配色函數數據相同", "10° 觀察者只能用於光源色，不能用於物體色，因此多用於色度計算", "2° 適用於影像等小視角，10° 適用於大面積色樣"], "explain": "2° 觀察者依小視角色刺激建立，10° 依大視角建立；以 10° 計算的刺激值記為 X₁₀Y₁₀Z₁₀。", "trap": "適用情境對調。", "src": "科目三指引 1.3（第 2-16～2-17 頁）", "fam": "L13-3003", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3004", "codes": ["L13103", "L13102"], "diff": "中", "level": "理解", "stem": "A、B 兩色光以加法混合。下列關於混合光的敘述何者正確？", "opts": ["(x, y) 一定落在 A、B 連線上，亮度 Y 為兩者相加", "(x, y) 一定是兩點的簡單平均，亮度 Y 為兩者相加", "(x, y) 落在 A、B 連線上，亮度 Y 取兩者中較大的值", "(x, y) 可能落在 A、B 連線外，因為混色會產生新的色相"], "explain": "依格拉斯曼定律，兩色光混合後的色度點落在兩點連線上，偏向光量較多的一方；亮度具可加性。三色光混合則落在三點圍成的三角形內。", "trap": "簡單平均忽略了兩光的光量比例；亮度具可加性，不是取較大值。", "src": "科目三指引 1.4（第 2-20 頁）", "fam": "L13-3004", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3005", "codes": ["L13205"], "diff": "易", "level": "理解", "stem": "四色印刷設定「總墨量上限（TAC）」約 300%，主要目的是什麼？", "opts": ["避免墨層過厚造成乾燥不良、背印或變形", "增加 CMY 三色的用量，以擴大可印出的色域", "限制黑版用量，讓暗部層次不會被 K 墨壓暗", "讓 RGB 影像可以不經轉換直接輸出到印刷機"], "explain": "四色疊印理論上限 400%，墨量過多會乾燥不良、變形。超過上限時優先保留 K、等比例降低 CMY，這也是底色去除（UCR）的由來。", "trap": "TAC 是限制總墨量而不是增加；超過上限時優先保留 K、降低 CMY，與限制黑版的方向相反。", "src": "科目三指引 2.3（第 2-47 頁）", "fam": "L13-3005", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3006", "codes": ["L13203", "L13102"], "diff": "中", "level": "理解", "stem": "影片壓縮常先把 RGB 轉成 YCbCr，再降低 Cb、Cr 的解析度。這樣做的依據是？", "opts": ["人眼對色差細節的解析力較高，對亮度的解析力較低", "人眼對亮度細節的解析力較高，對色差的解析力較低", "YCbCr 是裝置無關色空間，降低解析度不會影響色彩", "Cb、Cr 主要帶有雜訊資訊，刪減後反而能提升畫質"], "explain": "Y 接近明度訊號，Cb、Cr 是藍黃與紅綠的色差訊號。人眼對色差的空間解析力較低，所以降低色差通道解析度，畫面差異不明顯，卻能大幅壓縮資料量。", "trap": "與可視度題組呼應：細節辨識主要靠明度。", "src": "科目三指引 2.3（第 2-43 頁）", "fam": "L13-3006", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3007", "codes": ["L13204", "L13202"], "diff": "中", "level": "應用", "stem": "光圈不變，快門由 1/60 秒改為 1/125 秒（約少一半曝光量）。要讓影像亮度維持不變，ISO 應如何調整？", "opts": ["由 ISO 100 降低到約 ISO 50", "ISO 不需調整", "由 ISO 100 提高到約 ISO 200", "由 ISO 100 提高到約 ISO 400"], "explain": "曝光時間減半，Tv 級數加 1，曝光量少一級；把感光度提高一倍（Sv 加 1）即可補償。", "trap": "APEX 每一級代表兩倍，提高到 ISO 400 會多補一級。", "src": "科目三指引 2.3（第 2-44 頁）", "fam": "L13-3007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3008", "codes": ["L13104"], "diff": "易", "level": "應用", "stem": "同一款手機殼有亮面版與霧面版，品管要客觀比較兩者的「光澤」差異，應使用哪一種儀器與單位？", "opts": ["分光光度儀，以 ΔE*ab 表示", "濃度計，以反射濃度 D 表示", "色度計，以 xy 色度座標表示", "光澤計，以 GU（光澤單位）表示"], "explain": "光澤計量測鏡面反射方向的光強度，以高光澤黑玻璃為 100 GU 的相對值。色差、濃度、色度座標描述的都是顏色，不是光澤。", "trap": "", "src": "科目三指引 2.1（第 2-33 頁）", "fam": "L13-3008", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3009", "codes": ["L13206"], "diff": "易", "level": "應用", "stem": "學校制服洗了幾次後明顯褪色。這屬於哪一項紡織品質問題，出貨前應檢測什麼？", "opts": ["同色異譜，應在 D65、A 等多種光源下比色確認", "演色性不足，應改善店內燈光的 Ra 值後再比色", "光澤下降，應以光澤計量測洗前洗後的光澤度", "色牢度不足，應做水洗、摩擦、日曬等色牢度測試"], "explain": "色牢度是染色品經各種加工與使用後保持原色的能力，水洗褪色正是色牢度問題。", "trap": "同色異譜、演色性、光澤都是真實的品質概念，但洗後褪色是染料保持原色能力的問題。", "src": "科目一指引 1.4（第 2-15 頁）", "fam": "L13-3009", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-3010", "codes": ["L13307", "L13202", "L13105"], "diff": "難", "level": "分析", "stem": "客戶依 5 cm 小色票選定牆面色，漆滿整面牆後卻覺得「太鮮、太亮」，但量測牆面與色票的 ΔE 很小。下列解釋何者最恰當？", "opts": ["色外貌會隨面積、背景與觀看條件改變，ΔE 未納入這些條件", "牆面與色票發生了同色異譜，換到另一種光源下就會變得一致", "量測儀器的孔徑太小，無法代表整面牆，實際 ΔE 應該很大", "ΔE 小代表看起來相同，客戶的感覺是心理因素造成的錯覺"], "explain": "同一色度值，大面積時通常看起來更亮、更鮮豔（面積效應）。CIELAB 色差不處理面積、背景、適應等條件，所以要用色外貌模式描述，實務上也應以大尺寸色板試色。", "trap": "同色異譜需要光譜不同的兩個樣本，同一種漆不成立；「數值相同＝看起來相同」是色彩管理最常見的誤解。", "src": "吳瑞卿簡報（CIECAM02 考慮因素）；科目二指引 2.1 注意事項", "fam": "L13-3010", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-3011", "codes": ["L13306", "L13203"], "diff": "中", "level": "應用", "stem": "影片後製公司要交付同一支影片給網路平台（sRGB／Rec.709）、數位電影院（DCI-P3）與 HDR 電視（Rec.2020）。若以色域最大的版本為母片，往其他規格轉換時，下列敘述何者正確？", "opts": ["DCI-P3 的色域比 Rec.2020 大，應以 DCI-P3 為母片", "Rec.2020 母片轉到 DCI-P3 與 sRGB 時，部分高彩度色會超出目標色域，需要色域對映處理", "sRGB 與 Rec.2020 色域相同，轉換時不需處理", "三種規格的白點不同，色域大小則完全相同"], "explain": "色域大小為 Rec.2020 ＞ DCI-P3 ＞ sRGB（Rec.709），三者多以 D65 為白點。由大色域往小色域轉換時，超出的顏色要依演色方式對映。", "trap": "", "src": "科目三指引 2.3（第 2-42～2-43 頁）", "fam": "L13-3011", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-3012", "codes": ["L13301", "L13304", "L13302"], "diff": "難", "level": "分析", "stem": "設計部門有 10 台螢幕，同一張圖在每台上顏色都不同。要讓顏色盡量一致，下列流程何者最合理？", "opts": ["把每台螢幕的 RGB 增益與亮度滑桿調成相同數值，再套用同一個描述檔", "用校色器量測其中一台產生描述檔，再把這個描述檔套用到其他螢幕", "用校色器把每台校準到相同目標，再量測產生各自的描述檔", "用分光光度儀搭配白板校正量測紙張，再把結果套用到螢幕"], "explain": "螢幕是裝置相關色，同樣的設定值在不同螢幕上不會一樣。要先校準到相同目標，再分別做特性描述產生各自的描述檔（3C 的前兩步）。量測螢幕要用測光源色的儀器。", "trap": "「同設定值」與「同描述檔」都忽略了每台裝置的個體差異。", "src": "徐明景簡報（3C）；科目三指引 2.1", "fam": "L13-3012", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-3013", "codes": ["L13101", "L13103"], "diff": "中", "level": "理解", "stem": "兩盞 LED 燈都標示相關色溫 4000 K，但一盞明顯偏綠、一盞偏洋紅。下列解釋何者正確？", "opts": ["CCT 只是一維資訊；兩燈偏離黑體軌跡的方向不同，需搭配 Duv 描述", "兩燈的演色性 Ra 不同；偏色是演色性造成，而非色度座標不同", "兩燈的色溫標示錯誤；CCT 相同時光色就相同", "兩燈的光通量不同；需改以照度 lx 描述才能區分光色"], "explain": "色彩是二維色度資訊，CCT 只取最接近的黑體色溫。同一條等色溫線上的光可能偏綠或偏洋紅，照明業以 Duv 表示偏離黑體軌跡的程度。", "trap": "CCT 相同不代表光色相同；演色性描述物體色的再現，不是光源本身的色度；照度只是光量。", "src": "科目三指引 1.2（第 2-10～2-11 頁）", "fam": "cct", "type": "mc", "subj": "L13", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4001", "codes": ["L11101", "L11301"], "diff": "中", "level": "應用", "stem": "某銀行把品牌色由紅改為深藍，希望傳達「穩健、可信賴」。這主要運用了色彩的哪些功能？", "opts": ["物體辨識功能", "象徵性與情緒影響功能", "指示性功能", "美感功能以外的任何功能都無關"], "explain": "色彩在特定文化中累積的象徵意義（藍＝理性、科學、可靠），以及對情緒的影響，是品牌用色的主要依據。", "trap": "指示性是用來區分類別或標示數值；這裡要傳達的是意義與感受。", "src": "科目一指引 1.1、3.1（第 2-2、2-43 頁）", "fam": "L11-4001", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4002", "codes": ["L11101", "L11302", "L11205"], "diff": "難", "level": "分析", "stem": "醫院要重新規劃院內指標系統。下列哪一個色彩規劃方向，最能同時兼顧色彩的「指示性功能」與實際可用性？", "opts": ["全館指標統一使用品牌主色，以單一顏色建立整體的辨識系統", "各區以不同色相區分即可，色相差夠大時不必另外考慮明度差", "各區使用多種鮮豔顏色，以豐富的色彩變化提高辨識與趣味", "各區指定一個主色，並確保字與底的明度差，搭配編號與圖示"], "explain": "色彩編碼要讓類別清楚可辨（指示性），也要兼顧可視度（明度差）與通用設計（不只靠顏色）。統一單色無法區分區域；色彩過多會降低辨識效率。", "trap": "統一單色無法區分區域；只靠色相忽略了可視度與色覺異常者；色彩過多反而降低編碼的辨識效率。", "src": "科目一指引 1.1、3.2；謝翠如簡報（校園指標專案）", "fam": "L11-4002", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4003", "codes": ["L11103", "L11104", "L11301"], "diff": "難", "level": "分析", "stem": "服飾店試衣間使用 2700 K、Ra 80 的暖光，顧客常抱怨「在店裡很好看，回家看顏色不一樣」。下列改善方式何者最合理？", "opts": ["維持 2700 K 但提高照度，讓衣服的顏色看得更清楚", "改用更低色溫的燈，讓衣服在店內看起來更溫暖討喜", "改用約 4000–5000 K、Ra ≥ 90 的光源", "把燈光調暗，降低顧客對店內與家中色差的感知"], "explain": "低色溫加上演色性不足，物體色會偏黃且失真；顧客回家在不同光源下看到的顏色自然不同（加上色彩恆常性也不完全）。提高演色性、使用接近日常的色溫，並提供對照光源最合理。", "trap": "照度與色溫、演色性是不同的指標；降低色溫或調暗燈光只會讓店內外的色差更大或更難察覺。", "src": "科目一指引 1.3、1.4、3.1", "fam": "L11-4003", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4004", "codes": ["L11104", "L11103", "L11106"], "diff": "難", "level": "分析", "stem": "舞台上一件白色戲服，同時被一盞紅色投射燈與一盞綠色投射燈照亮的區域，看起來最可能是什麼顏色？若改成紅色戲服在同樣的照明下呢？", "opts": ["白戲服偏黃；紅戲服也偏黃", "白戲服偏黃；紅戲服接近紅", "白戲服偏洋紅；紅戲服接近黑", "白戲服仍是白；紅戲服仍是紅"], "explain": "紅光與綠光投射在同一位置是加法混色，白色表面反射兩者，看起來偏黃。紅色物體主要只反射紅光、吸收綠光，所以看起來是紅色（亮度略低）。", "trap": "白戲服同時反射紅光與綠光，呈現加法混色的黃；紅戲服主要只反射紅光、吸收綠光，所以不會跟著變黃。", "src": "科目一指引 1.4、1.6", "fam": "L11-4004", "type": "mc", "subj": "L11", "dom": "D1", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4005", "codes": ["L11105", "L12102", "L11205"], "diff": "難", "level": "分析", "stem": "室內設計公司要和歐洲建材商溝通牆面色彩，對方使用 NCS，設計師手邊是孟塞爾色票。下列做法何者最恰當？", "opts": ["量測實體色樣的 CIELAB 值作為共同基準，再對應雙方的標記", "依孟塞爾與 NCS 的換算規則，把明度、彩度數字直接轉成 NCS 寫法", "兩體系的色相環都以五主色為基礎，可依色相位置直接對照", "以雙方都熟悉的英文色名溝通，再請對方寄色樣確認"], "explain": "孟塞爾（明度、彩度）與 NCS（含黑度、含白度、彩度；四主色）建構原理不同，無法用數字直接換算。以裝置無關的 CIELAB 為共同基準，再以實體色樣確認最可靠。", "trap": "孟塞爾與 NCS 建構原理不同，數字無法直接換算；NCS 依對立色理論只有四個主色；色名缺乏精確性。", "src": "科目一指引 1.5；科目二指引 1.2", "fam": "L11-4005", "type": "mc", "subj": "L11", "dom": "D2", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4006", "codes": ["L11202"], "diff": "易", "level": "理解", "stem": "CIELAB 的明度 L* 不直接使用光線強度比例 Y/Yn，而是取其立方根再換算。主要原因是？", "opts": ["立方根運算較簡便，方便在早期計算機上處理", "為了讓黑色的 L* 等於 100、白色等於 0", "為了配合印刷油墨濃度與網點擴大的特性", "人對明度的感覺與物理光強度呈非線性關係"], "explain": "光強度加倍，明度感覺並不會加倍。心理物理學把物理刺激量與主觀感覺對應起來，L* 公式就是這種非線性對應的結果。", "trap": "L* 是心理物理學的非線性對應，與運算方便或印刷條件無關；L* 的範圍是黑 0、白 100。", "src": "科目一指引 2.2（第 2-28 頁）", "fam": "L11-4006", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4007", "codes": ["L11202", "L11206", "L13105"], "diff": "難", "level": "分析", "stem": "印刷廠與客戶約定「樣品與標準的 ΔE*ab 不得超過 2」。某批產品量得 ΔE*ab ＝ 1.8，客戶目視卻認為明顯偏色。下列判斷何者最合理？", "opts": ["ΔE*ab 未超過 2 即屬合格；應以數據說服客戶接受", "ΔE*ab 主要反映明度差，對色相與彩度差不敏感；應另外量測再判定", "CIELAB 不完全均勻；應目視確認並考慮改用 CIEDE2000", "允差訂得太嚴格；應把規格放寬到 ΔE*ab ≤ 10 以避免爭議"], "explain": "ΔE*ab 是把感覺轉成數字的近似工具，在某些色區與條件下與目視不一致。規格要搭配目視確認與更貼近感覺的色差公式。", "trap": "ΔE*ab 包含明度、紅綠、黃藍三軸的差異。", "src": "科目一指引 2.2；科目二指引 2.1；科目三指引 2.2", "fam": "L11-4007", "type": "mc", "subj": "L11", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4008", "codes": ["L11203", "L11207"], "diff": "中", "level": "理解", "stem": "一張照片從數位相機拍攝、在螢幕上編修、再由噴墨印表機輸出。關於這個色彩複製流程，下列敘述何者正確？", "opts": ["三種裝置都使用加法混色，因此校正螢幕亮度後顏色就能一致", "相機與螢幕同屬 RGB，數值相同時顏色就相同，差異在印表機端", "各環節的成像原理與色域不同，需要以色彩管理控制差異", "色彩複製的差異來自墨水品質，更換原廠墨水即可解決"], "explain": "相機以感光元件擷取、螢幕以 RGB 子畫素發光或透光（加法混色）、噴墨以 CMYK 網點（減法）呈現，色域與原理都不同，所以要靠色彩管理維持一致。", "trap": "相機、螢幕是 RGB 加法，噴墨是 CMYK 減法；即使同為 RGB 裝置，相同數值也不代表相同顏色。", "src": "科目一指引 2.3、2.7", "fam": "L11-4008", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4009", "codes": ["L11204"], "diff": "易", "level": "理解", "stem": "影像軟體的選色介面常用「色相環＋彩度／明度方塊」呈現。這樣設計的主要原因是？", "opts": ["色彩有三個屬性，介面要讓三維的色彩在二維畫面上操作", "螢幕的色彩是二維的，因此以平面圖形表示兩個色彩屬性", "色相環是 CMYK 印刷的標準，介面沿用以便與印刷端對應", "此設計可讓所選顏色自動落在印刷色域內，避免超出色域"], "explain": "色彩有三個屬性，選色介面多半以色相為主要選擇維度，再搭配彩度與明度調整。", "trap": "螢幕色彩仍有三個屬性；色相環不是 CMYK 印刷標準，選色介面也不會自動把顏色限制在印刷色域內。", "src": "科目一指引 2.4（第 2-31 頁）", "fam": "L11-4009", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4010", "codes": ["L11203", "L11206"], "diff": "中", "level": "理解", "stem": "同一份商品照片要用在電商網頁與印刷型錄。下列對「好的色彩複製」的理解何者正確？", "opts": ["兩個媒介使用相同的 RGB 數值，就能確保複製品質良好", "可用色差做客觀評估，也要依用途、觀看條件與需求做主觀評估", "以色差數值為準，用途與觀看條件屬於主觀因素，不宜納入評估", "印刷品應比螢幕更鮮豔，以補償紙張反射光較弱的落差"], "explain": "色彩複製品質可以客觀（色差）或主觀（用途、偏好、需求）衡量，兩者常同時使用。", "trap": "RGB 數值相同不代表兩個媒介呈現的顏色相同；只看色差數值則忽略了用途與觀看條件。", "src": "科目一指引 2.3（第 2-30 頁）", "fam": "repro", "type": "mc", "subj": "L11", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4011", "codes": ["L11207"], "diff": "易", "level": "理解", "stem": "單晶片 DLP 投影機只有一顆 DMD 晶片，它如何呈現全彩影像？", "opts": ["晶片上排列紅、綠、藍子畫素，以並置混色合成全彩", "光線依序通過青、洋紅、黃濾鏡，以減法混色合成全彩", "DMD 晶片本身依訊號發出紅、綠、藍光，直接合成全彩", "光源經色輪依序產生紅、綠、藍光，以時序混色合成"], "explain": "單晶片 DLP 以色輪輪流投出 RGB，DMD 微鏡偏轉控制每個畫素各色的出光時間，眼睛的時間解析力不足而把它們混合。", "trap": "並置混色是 LCD／OLED 子畫素的機制；DMD 是反射光線的微鏡，本身不發光。", "src": "科目一指引 2.7（第 2-39 頁）", "fam": "dlp", "type": "mc", "subj": "L11", "dom": "D3", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4012", "codes": ["L11401"], "diff": "易", "level": "理解", "stem": "客戶說：「我要同一個藍，但淺一點、柔和一點。」用 PCCS 的概念來看，設計師要調整的是什麼？", "opts": ["色相，改成偏綠或偏紫的淺藍", "明度，提高明度就會同時變淺變柔和，色相與彩度不變", "改用另一個色彩體系，重新選出柔和的藍", "色調（明度與彩度的組合），色相不變"], "explain": "PCCS 以「色相＋色調」描述色彩。「淺、柔和」是色調形容詞（例如 lt、sf），同時牽涉明度與彩度；「同一個藍」表示色相不變。", "trap": "口語中的淺、深、柔、鮮，多半是色調而不是色相的變化；「柔和」牽涉彩度，單調明度無法做到。", "src": "科目一指引 4.1；科目二指引 1.1", "fam": "pccs", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L11-4013", "codes": ["L11401", "L11402", "L11205"], "diff": "難", "level": "分析", "stem": "兒童益智玩具品牌希望包裝「活潑、繽紛，但不雜亂」。下列哪一個配色策略最符合色彩秩序的原則？", "opts": ["在同一明亮色調中選用多個不同色相", "每個元素各自挑選不同色調、不同色相的鮮豔色", "以灰色調為主，再用一個高彩度色點綴", "選用同一色相，以不同明度的變化製造層次"], "explain": "指引認為美感來自潛藏的秩序：固定一個屬性（色調）、只變化另一個屬性（色相），可以同時得到繽紛與統一。", "trap": "色相與色調同時大幅變化容易雜亂；同色相配色無法達到繽紛。", "src": "科目一指引 4.1、4.2；李文淵簡報", "fam": "L11-4013", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L11-4014", "codes": ["L11402", "L11303", "L12201"], "diff": "難", "level": "分析", "stem": "運動品牌主視覺用紅色字放在綠色背景上（互補色、彩度都高），在大型看板上顯得刺眼且邊緣閃爍。下列調整何者最能保留「強烈對比」又改善問題？", "opts": ["把紅字改成與綠色背景同色相，以明度差維持可讀性", "保留互補色相，拉開明度差並加白色或黑色描邊", "把兩色的彩度都再提高，強化互補色的對比張力", "改用鄰近色配色，以溫和的色相差降低閃爍感"], "explain": "互補色並置會產生強烈的色相對比；明度相近時又會產生色滲與閃爍。拉開明度差、以中性色描邊，可保留色相對比，同時改善可讀性。", "trap": "改成鄰近色或同色相會失去品牌要的強烈對比。", "src": "科目一指引 3.3、4.2；科目二指引 2.3", "fam": "L11-4014", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L11-4015", "codes": ["L11404"], "diff": "易", "level": "理解", "stem": "選擇色相、明度一致，只有彩度不同的顏色互相搭配，通常會產生什麼效果？", "opts": ["強烈刺激、對比鮮明，適合作為強調色", "繽紛活潑，適合作為兒童商品用色", "緩和、淡雅，適合作為背景用色", "混濁、沉重，適合作為正式場合用色"], "explain": "以彩度為主的配色中，同色相、同明度、不同彩度的組合，視覺上緩和淡雅。", "trap": "色相與明度都一致、只有彩度差的組合對比很弱，不會產生強烈刺激或繽紛效果。", "src": "科目一指引 4.4（第 2-57 頁）", "fam": "L11-4015", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L11-4016", "codes": ["L11404", "L11301", "L11205"], "diff": "難", "level": "分析", "stem": "一家精品咖啡店要同時推出兩條產品線：給年輕上班族的「活力系列」與給熟客的「經典系列」。依以彩度為主的配色原則，下列規劃何者最合適？", "opts": ["活力系列用低彩度、經典系列用高彩度，以彩度反差區隔兩條產品線", "兩系列都採高彩度同彩度組，差異在 logo 大小與版面配置", "活力系列用高彩度同彩度組，經典系列用中低彩度組，共用部分色相", "兩系列各自挑選不重複的色相與彩度，以強調產品線的差異化"], "explain": "高彩度同彩度組傳達活潑年輕，中低彩度組傳達穩重成熟；共用色相能在差異化之外維持品牌一致化。", "trap": "高彩度對應活潑年輕、中低彩度對應穩重成熟，方向顛倒是常見錯誤；兩系列完全不共用色相則失去品牌一致性。", "src": "科目一指引 4.4；科目二指引 2.1（色彩計畫四特性）", "fam": "L11-4016", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4001", "codes": ["L13104", "L13207", "L13105"], "diff": "難", "level": "分析", "stem": "同一塊金屬漆樣品，A 廠用 45°/0° 儀器、B 廠用 d/8°（SPIN）儀器量測，兩邊的 L*a*b* 差很多，雙方都說自己的數據才對。下列處置何者最恰當？", "opts": ["以 d/8° SPIN 的數據為準，因為積分球幾何較能代表金屬漆的顏色", "雙方先約定相同的量測幾何、光源與觀察者，再比較數據", "兩廠數據取平均，以抵銷不同儀器的系統誤差", "改用光澤計量測，就能得到不受幾何影響的 L*a*b*"], "explain": "量測幾何會影響結果，高光澤或金屬漆尤其明顯。CIE 規範幾何條件，就是為了讓不同儀器能得到可比較的數據。光澤計只量光澤度，無法得到色度值。", "trap": "幾何條件不同的數據本來就不能直接比較，沒有哪一種幾何「天生正確」；取平均無意義；光澤計量不到色度值。", "src": "科目三指引 2.1（第 2-33～2-36 頁）", "fam": "L13-4001", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4002", "codes": ["L13105"], "diff": "易", "level": "理解", "stem": "CIELAB 色差公式中，ΔE*ab ≈ 1 通常被視為什麼？", "opts": ["約為人眼恰可察覺的色差", "約為人眼一眼就能看出的明顯色差", "代表兩色的明度差 ΔL* 等於 1", "代表兩色的光譜反射率相同"], "explain": "ΔE*ab ＝ 1 約為人眼恰可察覺的色差（實際依色區與條件而異）。", "trap": "ΔE 是三個分量合成的總色差，不等於明度差；色差小也不代表光譜相同。", "src": "科目三指引 2.2（第 2-39 頁）；吳瑞卿簡報", "fam": "L13-4002", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4003", "codes": ["L13201"], "diff": "易", "level": "知識", "stem": "色彩複製（color reproduction）的基本架構，下列描述何者正確？", "opts": ["原稿經再現過程產生光譜與原稿相同的複製物", "原稿經數位設備之間的檔案傳遞產生複製物", "原稿經印刷機重新印製，產生與原稿相同的印刷品", "原稿經照相、印刷、顯示等再現過程產生複製物"], "explain": "原稿可以是場景或物體，經各種成像技術再現為複製物；目標通常是色彩感覺一致，而非光譜相同。", "trap": "色彩複製的目標通常是色彩感覺一致而非光譜相同，原稿與再現方式也不限於印刷或數位設備。", "src": "科目一指引 2.3；陳鴻興簡報（色彩再現之意義）", "fam": "L13-4003", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4004", "codes": ["L13201", "L13203", "L13205"], "diff": "難", "level": "分析", "stem": "博物館要把一幅古畫數位典藏，並同時用於網站展示與高品質複製畫印刷。下列流程何者最合理？", "opts": ["以標準照明與色導表拍攝，先轉成 CMYK 保存母檔；網站版再從 CMYK 轉回 sRGB", "以標準照明拍攝並存成 sRGB 母檔，網站與印刷都直接使用同一個檔案", "以標準照明與色導表拍攝，母檔在校準螢幕上確認與原畫一致即可，不需打樣", "以標準照明與色導表拍攝，大色域母檔保存；網站轉 sRGB，印刷依描述檔轉換並打樣"], "explain": "母檔應保留最多色彩資訊並有色彩參考；不同輸出媒介色域不同，要分別轉換。先轉成較小色域的 CMYK 會永久失去色彩資訊。", "trap": "先轉成小色域會永久失去色彩資訊；不同輸出媒介要分別轉換；螢幕與印刷色域不同，印刷仍需打樣。", "src": "科目三指引 2.3；陳鴻興簡報；徐明景簡報", "fam": "L13-4004", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4005", "codes": ["L13202"], "diff": "易", "level": "知識", "stem": "CIE 建議目視比較色差時的觀看條件，下列何者正確？", "opts": ["D65 光源、約 1000 lx、L*≈50 的中灰背景", "A 光源、約 1000 lx、L*≈50 的中灰背景", "D50 光源、約 2000 lx、白色背景", "D65 光源、約 1000 lx、黑色背景以凸顯色差"], "explain": "指引列出 CIE 建議：照度約 1000 lx 的 D65 光源、中灰背景（L*a*b* ≈ 50, 0, 0）、相鄰兩樣本、視角大於 4°。", "trap": "D50 是印刷對色常用光源但非 CIE 色差觀看建議；背景顏色會影響色差判斷，應為中灰。", "src": "科目三指引 2.2（第 2-40 頁）", "fam": "viewcond", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4006", "codes": ["L13206", "L13105"], "diff": "中", "level": "應用", "stem": "紡織業評估色差時，常把 CIEDE2000 的權重設為 (kL, kC, kH) ＝ (2, 1, 1)。這代表什麼？", "opts": ["提高明度差的權重為兩倍，因為布料對明度差最敏感", "降低明度差在色差中的權重", "降低彩度與色相差的權重，使明度差相對較重要", "允許的明度差上限為 2 個單位"], "explain": "k 值越大，該分量在公式中被除得越多，權重越低。紡織品表面紋理使明度差較不敏感，因此 kL ＝ 2。", "trap": "k 值與權重是反向關係，最常被理解反。", "src": "科目三指引 2.2（第 2-40 頁）", "fam": "kL", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4007", "codes": ["L13207"], "diff": "易", "level": "理解", "stem": "同一個顏色做成高光澤與霧面兩種表面，在一般室內觀看時，下列敘述何者正確？", "opts": ["表面處理會改變色外貌，霧面因散射較多，通常看起來更深、更飽和", "表面處理主要影響手感與耐刮性，色料相同時顏色就相同", "表面處理會改變色外貌，高光澤面避開反光時通常看起來更深、更飽和", "表面處理會改變色相，高光澤面通常偏藍、霧面通常偏黃"], "explain": "光澤影響鏡面反射與擴散反射的比例，進而改變色外貌，因此 CMF 設計要同時考慮色彩、材質與表面處理。", "trap": "霧面的表面散射會混入白光，讓顏色顯得較淺、較灰；光澤改變的是明度與飽和感，不是色相。", "src": "科目一指引 1.1、1.4；科目二指引 2.1", "fam": "L13-4007", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4008", "codes": ["L13207", "L13104", "L13302"], "diff": "難", "level": "分析", "stem": "3C 外殼同一色號分別用塑膠射出（霧面）與金屬烤漆（高光澤）兩種製程，量產後並排總覺得不一樣。下列品管策略何者最恰當？", "opts": ["兩種材質都使用同一個 L*a*b* 標準值與允差，並以同一台儀器量測", "統一兩廠的色料配方，配方相同就能確保量產外觀一致", "依材質分別建立標準樣與允差，統一量測幾何，並在標準光源下目視確認", "以螢幕截圖的 RGB 值作為兩廠共同標準，並在標準光源下目視確認"], "explain": "材質與表面處理不同，同樣色料也會有不同色外貌，量測值也受幾何條件影響。CMF 品管要為不同材質分別建立標準，並統一量測與觀看條件。", "trap": "同色料在不同材質與表面處理下色外貌不同，量測值也受幾何影響，單一標準值不足以管控；RGB 是裝置相關色。", "src": "科目三指引 2.1；職能基準 T3c（CMF 領域）", "fam": "L13-4008", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4009", "codes": ["L13301"], "diff": "易", "level": "知識", "stem": "色彩管理系統最核心的目標是什麼？", "opts": ["讓色彩在不同裝置與媒介間盡量維持一致", "讓 RGB 數值在不同裝置與媒介間保持相同", "讓每台螢幕都能顯示其色域內最鮮豔的顏色", "統一印刷與顯示流程，以降低打樣與印刷成本"], "explain": "色彩管理希望色彩經過複製或生產後，仍能穩定呈現原本設定的樣子（WYSIWYG）。", "trap": "RGB 數值相同不等於顏色相同。", "src": "科目一指引 2.6（第 2-35 頁）；徐明景簡報", "fam": "L13-4009", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4010", "codes": ["L13301", "L13303"], "diff": "中", "level": "理解", "stem": "徐明景老師以「翻譯」比喻色彩管理：法文要翻成日文，先翻成英文當中介。對應到色彩管理系統，下列何者正確？", "opts": ["RGB、CMYK 是裝置相關的語言，描述檔是中介，CIELAB（PCS）是字典", "RGB、CMYK 是裝置相關的語言，CIELAB（PCS）是中介，描述檔是字典", "RGB、CIELAB 是兩端的語言，CMYK 是中介，描述檔是字典", "RGB、CMYK 是同一種語言，不需中介，描述檔用來壓縮檔案"], "explain": "色彩管理透過描述檔把裝置訊號轉到裝置無關的 PCS（CIELAB），再轉到目標裝置，CIELAB 擔任中介的角色。", "trap": "描述檔與 PCS 的角色對調是最常見的混淆：PCS 是中介空間，描述檔記錄各裝置與 PCS 的對應。", "src": "徐明景簡報（色彩對應的原理）", "fam": "L13-4010", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4011", "codes": ["L13303", "L13305"], "diff": "中", "level": "理解", "stem": "色彩管理系統要完成一次 RGB 到 CMYK 的轉換，下列哪一組元件缺一不可？", "opts": ["來源描述檔、目的描述檔與演色意圖即可，不需要色彩轉換引擎", "來源與目的描述檔即可，CMM 與演色意圖可省略", "目的描述檔與 CMM 即可，來源預設為 sRGB 就好", "來源描述檔、目的描述檔、色彩轉換引擎（CMM），並選定演色意圖"], "explain": "轉換需要前端描述檔（RGB → PCS）、後端描述檔（PCS → CMYK）、色彩引擎執行運算，再依演色意圖處理色域外的顏色。", "trap": "描述檔只是對應資料，需要 CMM 執行運算；缺少來源描述檔時，RGB 數值的意義無法確定。", "src": "科目一指引 2.6；徐明景簡報（Photoshop 實務應用）", "fam": "L13-4011", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4012", "codes": ["L13304"], "diff": "易", "level": "知識", "stem": "螢幕校色常用的「校色器」，一般屬於哪一類量測儀器？", "opts": ["分光光度儀，量測前需以白板校正", "濃度計，以狀態 T 濾鏡量測各色墨層", "光澤計，以 60° 幾何量測表面反光", "色度計，以寬頻濾鏡模擬色匹配函數"], "explain": "色度計以寬頻濾鏡感光，準確度不如光譜儀但輕便，適合螢幕色彩校正與色差比較。", "trap": "分光光度儀量表面色、濃度計量印刷墨層、光澤計量光澤，都不是一般螢幕校色器的類型。", "src": "科目三指引 2.1（第 2-32 頁）", "fam": "L13-4012", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4013", "codes": ["L13304", "L13302"], "diff": "中", "level": "應用", "stem": "螢幕校準完成並產生描述檔後，三個月後色彩開始偏移。下列做法何者正確？", "opts": ["保留原描述檔，調整作業系統的亮度滑桿即可", "定期重新校準與特性描述", "描述檔長期有效，偏移是環境光造成的錯覺", "下載同型號螢幕的廠商描述檔來取代"], "explain": "特性描述的前提是裝置維持在校準後的穩定狀態；裝置漂移後，舊描述檔就不再準確，需要定期重做。", "trap": "顯示器會老化漂移，舊描述檔描述的已不是目前的狀態；同型號的廠商描述檔不反映個體差異。", "src": "徐明景簡報（3C、穩定環境）", "fam": "L13-4013", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4014", "codes": ["L13305"], "diff": "易", "level": "理解", "stem": "在色彩管理系統中選擇演色意圖（rendering intent），主要應依據什麼來決定？", "opts": ["來源與目的裝置的品牌，同品牌時可省略", "目的色域大小，色域越大越要選飽和度式", "影像內容與用途，例如自然影像或商業圖表", "固定使用同一種意圖，以確保整批檔案結果一致"], "explain": "四種演色意圖處理色域外顏色的方式不同：感應式適合自然影像，飽和度式適合商業圖表，色度式適合重視色度準確的打樣。", "trap": "演色意圖處理色域外顏色的方式不同，應依影像內容與用途選擇，與裝置品牌或固定習慣無關。", "src": "科目一指引 2.6（第 2-36 頁）", "fam": "intent", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L13-4015", "codes": ["L13306"], "diff": "易", "level": "應用", "stem": "攝影師把 Adobe RGB 的照片直接上傳到網站，在一般瀏覽器上顏色看起來變灰、變淡。最可能的原因與正確做法是？", "opts": ["網頁多以 sRGB 解讀影像，上傳前應先轉換為 sRGB", "網頁多以 sRGB 解讀影像，上傳前應先把描述檔「指定」為 sRGB", "瀏覽器以 CMYK 解讀影像，上傳前應先轉換為 CMYK", "網站壓縮破壞了色彩，上傳前應改存成 PNG 格式"], "explain": "同一組 RGB 數值在 Adobe RGB 中代表較鮮豔的顏色；若被當成 sRGB 解讀，看起來就變灰。網頁用圖應先轉換為 sRGB。", "trap": "「指定」為 sRGB 只改變解讀、數值不變，照片一樣會變灰；要用「轉換」才會改數值保留外觀。", "src": "科目二指引 2.4；徐明景簡報（網頁預設 sRGB）", "fam": "srgb", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4016", "codes": ["L13306", "L13203", "L13305"], "diff": "難", "level": "分析", "stem": "品牌要同時在 HDR 廣色域電視廣告（Rec.2020 規格）、手機網頁（sRGB）與報紙（新聞紙印刷）呈現同一個鮮豔的品牌紅。下列策略何者最合理？", "opts": ["以 Rec.2020 的 RGB 數值定義品牌紅，再直接套用到網頁與報紙等其他媒介", "以報紙能印出的顏色定義品牌紅，再把其他媒介都調到與報紙相同", "以 sRGB 色碼定義品牌紅，各媒介再各自調整到看起來最鮮豔", "以 CIELAB 值與實體色樣定義品牌紅，再依各媒介分別訂出最接近的再現值"], "explain": "三種媒介的色域差異很大，同一數值不可能在所有媒介都相同。以裝置無關的標準定義品牌色，再依各媒介的色域與演色意圖分別處理，是跨媒體色彩管理的做法。", "trap": "RGB 色碼是裝置相關值，不能跨媒介直接套用；遷就最小色域會犧牲其他媒介，各自調到最鮮豔則失去一致性。", "src": "科目三指引 2.3；徐明景簡報", "fam": "L13-4016", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "D"}, {"id": "L13-4017", "codes": ["L13307"], "diff": "易", "level": "知識", "stem": "CIECAM02 這類「色外貌模式」相較於 CIELAB，多考慮了哪些因素？", "opts": ["色料的成分與濃度，以預測混色結果", "觀看背景、亮度適應、色適應等條件", "螢幕的解析度與更新率", "物體的光譜反射率與量測幾何條件"], "explain": "色外貌模式把背景、環境光、適應狀態等觀看條件納入，用來預測同一刺激在不同條件下看起來的樣子。", "trap": "色外貌模式處理的是觀看條件與適應狀態，不是色料、裝置規格或量測幾何。", "src": "吳瑞卿簡報（CIECAM02）", "fam": "L13-4017", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "B"}, {"id": "L13-4018", "codes": ["L13307", "L11301"], "diff": "中", "level": "理解", "stem": "同一張照片在昏暗的電影院大銀幕與明亮辦公室的手機上看，色彩感覺不同。下列哪一個概念最能說明為什麼需要「色外貌模式」？", "opts": ["色彩感覺受觀看環境與適應狀態影響，相同色度值看起來不同", "兩個裝置的 RGB 數值不同，換算成相同數值後就會一致", "手機色域比電影院大，所以手機上的顏色通常比較鮮豔", "ΔE*ab 為 0 時看起來就相同，差異來自兩裝置的量測誤差"], "explain": "色彩恆常性、亮度與色適應都會改變色外貌；CIELAB 未納入這些條件，因此需要色外貌模式。", "trap": "數值相同不代表看起來相同；觀看環境與適應狀態才是需要色外貌模式的原因。", "src": "科目一指引 3.1；吳瑞卿簡報", "fam": "L13-4018", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "A"}, {"id": "L13-4019", "codes": ["L13303", "L13302"], "diff": "中", "level": "應用", "stem": "在 Photoshop 中打開一張沒有嵌入描述檔的 RGB 照片。下列做法何者正確？", "opts": ["依影像來源判斷原色彩空間並「轉換」為 sRGB，輸出時再「指定」", "直接「轉換」為 CMYK，因為印刷流程最終都需要 CMYK 檔案", "依影像來源判斷原色彩空間並「指定描述檔」，輸出時再「轉換」", "不需處理，沒有描述檔時軟體會自動以正確的色彩空間解讀"], "explain": "沒有描述檔時，同樣的 RGB 數值意義不明，要先「指定」正確的來源描述檔來解讀數值；輸出到其他媒介時再「轉換」。", "trap": "「指定」是告訴系統數值代表什麼，「轉換」才會改變數值；沒有來源描述檔就無法正確轉換，順序對調是常見錯誤。", "src": "徐明景簡報（指定色彩描述檔）", "fam": "L13-4019", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v2", "diag": false, "ans": "C"}, {"id": "L12-5001", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "seq", "fam": "order-N", "ans": ["2", "1", "3", "4"], "stem": "下列 4 張為無彩色色票。請依「明度」由低到高排列。請依序輸入四個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "無彩色只有明度差異：色票 2（N 3）、色票 1（N 5）、色票 3（N 7）、色票 4（N 9）。", "trap": "無彩色是建立明度判斷的基準，排錯代表需要先練習灰階。", "src": "科目二評鑑內容 L12101", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "N 5", "hex": "#797979"}, {"label": "2", "spec": "N 3", "hex": "#474848"}, {"label": "3", "spec": "N 7", "hex": "#ADADAD"}, {"label": "4", "spec": "N 9", "hex": "#E3E3E3"}]}, {"id": "L12-5002", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "one", "fam": "maxC", "ans": ["4"], "stem": "下列色票色相與明度相同。請輸入「彩度最高」的色票編號。", "explain": "彩度最高的是 色票 4（5PB 5/10）。", "trap": "", "src": "科目二評鑑內容 L12101", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "2", "spec": "5PB 5/6", "hex": "#617BA2"}, {"label": "3", "spec": "5PB 5/4", "hex": "#6B7A94"}, {"label": "4", "spec": "5PB 5/10", "hex": "#437CBD"}]}, {"id": "L12-5003", "codes": ["L12101"], "diff": "易", "level": "理解", "type": "one", "fam": "maxL", "ans": ["2"], "stem": "下列色票中，「明度最高」的是哪一張？請輸入色票編號。", "explain": "明度依序為 色票 1（5G 3/4）（3）、色票 4（5PB 4/4）（4）、色票 3（5R 5/10）（5）、色票 2（N 7）（7）。", "trap": "高彩度的紅容易被誤認為較亮；明度與彩度要分開判斷。", "src": "科目二評鑑內容 L12101", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5G 3/4", "hex": "#24503D"}, {"label": "2", "spec": "N 7", "hex": "#ADADAD"}, {"label": "3", "spec": "5R 5/10", "hex": "#C45756"}, {"label": "4", "spec": "5PB 4/4", "hex": "#51617B"}]}, {"id": "L12-5004", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "fam": "find", "ans": ["3"], "stem": "規格為孟塞爾 5YR 6/8。請輸入最符合的色票編號。", "explain": "答案是 色票 3（5YR 6/8）。卡上同色相的 色票 1（5YR 4/6）、色票 2（5YR 7/8）、色票 4（5YR 8/4） 都是誘答。", "trap": "色票 2（5YR 7/8） 只差一階明度，最容易誤選。", "src": "科目二指引 1.2", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5YR 4/6", "hex": "#88532F"}, {"label": "2", "spec": "5YR 7/8", "hex": "#E69D64"}, {"label": "3", "spec": "5YR 6/8", "hex": "#CA834B"}, {"label": "4", "spec": "5YR 8/4", "hex": "#E9C0A2"}]}, {"id": "L12-5005", "codes": ["L12102"], "diff": "易", "level": "理解", "type": "one", "fam": "findN", "ans": ["3"], "stem": "規格為孟塞爾 N5（明度 5 的中性灰）。請輸入正確的色票編號。", "explain": "N5 是無彩色，彩度為 0：色票 3（N 5）。其他三張明度相同，但都帶有低彩度的色相。", "trap": "低彩度色在中灰背景上很容易被看成灰色，要仔細比較色相傾向。", "src": "科目二指引 1.2；李文淵簡報（無彩色定義）", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 5/2", "hex": "#8A7573"}, {"label": "2", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "3", "spec": "N 5", "hex": "#797979"}, {"label": "4", "spec": "5BG 5/2", "hex": "#647F7C"}]}, {"id": "L12-5006", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "set", "fam": "lowerC", "ans": ["3", "5"], "stem": "請選出所有「與主色色相、明度相同，但彩度較低」的色票。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。【全對全錯】", "explain": "符合條件的是明度 5、彩度低於 6 的 色票 5（5R 5/2）、色票 3（5R 5/4）。色票 2（5R 5/8） 彩度較高；其餘明度不同。", "trap": "色票 6（LCh 80/30/28） 是同色相的淺粉紅，明度不同；題目要同時考慮色相、明度與彩度三個條件。", "src": "科目二評鑑內容 L12101、L12102", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5R 3/6", "hex": "#743335"}, {"label": "2", "spec": "5R 5/8", "hex": "#B7605E"}, {"label": "3", "spec": "5R 5/4", "hex": "#9B6E6C"}, {"label": "4", "spec": "5R 6/6", "hex": "#C4827E"}, {"label": "5", "spec": "5R 5/2", "hex": "#8A7573"}, {"label": "6", "spec": "LCh 80/30/28", "hex": "#FFB4AD"}], "main": {"label": "主色", "spec": "5R 5/6", "hex": "#AA6765"}}, {"id": "L12-5007", "codes": ["L12201", "L12101"], "diff": "中", "level": "應用", "type": "set", "fam": "achro-accent", "ans": ["3", "4"], "stem": "版面以無彩色為大面積主色，要選兩張小面積點綴色，營造「搶眼」的無彩配有彩效果。請選出最合適的兩張。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。【全對全錯】", "explain": "無彩配有彩要搶眼，點綴色應是高彩度色：色票 4（5R 5/12）、色票 3（5Y 8/10）。低彩度的 /2 色與無彩色差異小，色票 5（N 5） 本身就是無彩色。", "trap": "", "src": "科目二指引 2.3（第 2-29 頁）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5BG 5/2", "hex": "#647F7C"}, {"label": "2", "spec": "5PB 5/2", "hex": "#737A86"}, {"label": "3", "spec": "5Y 8/10", "hex": "#E6C737"}, {"label": "4", "spec": "5R 5/12", "hex": "#D04C50"}, {"label": "5", "spec": "N 5", "hex": "#797979"}]}, {"id": "L12-5008", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "type": "set", "fam": "toneintone", "ans": ["3", "4"], "stem": "要以主色搭配「鄰近色配色法」（相近色相、相近色調）。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。（本題的「同色調」指 CIELAB 的 L* 與 C* 相近。）【全對全錯】", "explain": "與 5Y 相鄰的色相是 10YR 與 5GY，且色調相近：色票 3（10YR 7/4）、色票 4（5GY 8/4）。色票 6（LCh 80/30/270）、色票 2（LCh 80/30/350）、色票 5（5G 8/4） 色調相同但色相差較大（色相差配色）；色票 1（5Y 4/4） 同色相但色調差異大（色調差配色）。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "", "src": "科目二指引 2.3（第 2-32 頁）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5Y 4/4", "hex": "#6F5F30"}, {"label": "2", "spec": "LCh 80/30/350", "hex": "#F8B3D1"}, {"label": "3", "spec": "10YR 7/4", "hex": "#C7A97F"}, {"label": "4", "spec": "5GY 8/4", "hex": "#C2CE95"}, {"label": "5", "spec": "5G 8/4", "hex": "#9FD4B7"}, {"label": "6", "spec": "LCh 80/30/270", "hex": "#A3C9FE"}], "main": {"label": "主色", "spec": "5Y 8/4", "hex": "#D6C891"}}, {"id": "L12-5009", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "type": "set", "fam": "toneontone", "ans": ["1", "3", "6"], "stem": "要以主色搭配「色調差配色法」（同色相、不同色調）。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。（本題的「同色調」指 CIELAB 的 L* 與 C* 相近。）【全對全錯】", "explain": "同為 5PB 的三張：色票 1（5PB 7/4）、色票 6（5PB 3/4）、色票 3（5PB 5/10）。其餘色相不同。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "色票 5（10B 5/6） 與 5PB 相鄰、看起來很像，但色相不同。", "src": "科目二指引 2.3（第 2-33 頁）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5PB 7/4", "hex": "#9EAFC7"}, {"label": "2", "spec": "LCh 80/30/220", "hex": "#73D4E9"}, {"label": "3", "spec": "5PB 5/10", "hex": "#437CBD"}, {"label": "4", "spec": "5P 6/6", "hex": "#A38AB3"}, {"label": "5", "spec": "10B 5/6", "hex": "#48809F"}, {"label": "6", "spec": "5PB 3/4", "hex": "#374864"}], "main": {"label": "主色", "spec": "5PB 5/4", "hex": "#6B7A94"}}, {"id": "L12-5010", "codes": ["L12201", "L11302"], "diff": "難", "level": "應用", "type": "one", "fam": "visib-card", "ans": ["1"], "stem": "包裝背景色如上，要在上面放成分說明的小字。請輸入可視度最高的文字色票編號。", "explain": "可視度主要取決於明度差：背景明度約 8，色票 1（N 3） 明度 3，差距最大。色票 3（N 9） 與 色票 2（5GY 8/10） 明度接近背景；色票 4（5Y 6/8） 同色相、明度差小。", "trap": "白字在黃底上看似醒目，但明度差太小，遠看或小字時難以辨讀。", "src": "科目一指引 3.2；科目二指引 2.3", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "N 3", "hex": "#474848"}, {"label": "2", "spec": "5GY 8/10", "hex": "#B6D544"}, {"label": "3", "spec": "N 9", "hex": "#E3E3E3"}, {"label": "4", "spec": "5Y 6/8", "hex": "#AD9124"}], "main": {"label": "背景", "spec": "5Y 8/10", "hex": "#E6C737"}}, {"id": "L12-5011", "codes": ["L12201", "L12102"], "diff": "難", "level": "分析", "type": "one", "fam": "plan-3color", "stem": "為銀髮族保健品做包裝色彩提案，設計目標是「溫和、自然、安心」，採大面積主色＋輔色＋小面積點綴色。下列哪一組最符合色彩計畫原則？請輸入組別編號。", "explain": "溫和自然：大面積用高明度、低彩度的黃綠，輔色為相鄰色相的綠（鄰近色配色），小面積才用較強的橙色點綴，符合「大面積弱色、小面積強色」。以 5R 5/12 為主色的那組把最強的色放在大面積；以 N 3 為主色的那組整體低明度、偏沉重；以 5Y 8/10 為主色的那組三色都是高彩度，色相對比強烈。", "trap": "這題不考個人美感偏好，而是檢查能否用三屬性與配色原則說明選擇理由。", "src": "科目二指引 2.1、2.2、2.3；李文淵簡報（設計題怎麼考）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "groups": [{"label": "第 1 組", "chips": [{"label": "", "spec": "5Y 8/10", "hex": "#E6C737"}, {"label": "", "spec": "5PB 5/10", "hex": "#437CBD"}, {"label": "", "spec": "5RP 5/10", "hex": "#B95982"}]}, {"label": "第 2 組", "chips": [{"label": "", "spec": "5GY 8/4", "hex": "#C2CE95"}, {"label": "", "spec": "5G 6/4", "hex": "#6B9E85"}, {"label": "", "spec": "5YR 6/8", "hex": "#CA834B"}]}, {"label": "第 3 組", "chips": [{"label": "", "spec": "5R 5/12", "hex": "#D04C50"}, {"label": "", "spec": "5GY 8/4", "hex": "#C2CE95"}, {"label": "", "spec": "N 9", "hex": "#E3E3E3"}]}, {"label": "第 4 組", "chips": [{"label": "", "spec": "N 3", "hex": "#474848"}, {"label": "", "spec": "5P 3/6", "hex": "#5A3B67"}, {"label": "", "spec": "5RP 5/10", "hex": "#B95982"}]}], "ans": ["2"]}, {"id": "L12-5012", "codes": ["L12201", "L11403"], "diff": "中", "level": "應用", "type": "one", "fam": "value-mood", "stem": "品牌要表現「輕快、明朗」的感覺，依以明度為主的配色原則，下列哪一組最合適？請輸入組別編號。", "explain": "同為高明度（8–9）的組合給人輕快感；低明度組合則沉穩厚重。含 5R 5/12 的那組明度與彩度差異都大，屬強對比。", "trap": "", "src": "科目一指引 4.3（第 2-56 頁）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "groups": [{"label": "第 1 組", "chips": [{"label": "", "spec": "5R 5/12", "hex": "#D04C50"}, {"label": "", "spec": "N 3", "hex": "#474848"}, {"label": "", "spec": "5B 3/4", "hex": "#154E5E"}]}, {"label": "第 2 組", "chips": [{"label": "", "spec": "5P 3/6", "hex": "#5A3B67"}, {"label": "", "spec": "5G 3/4", "hex": "#24503D"}, {"label": "", "spec": "5R 3/6", "hex": "#743335"}]}, {"label": "第 3 組", "chips": [{"label": "", "spec": "N 3", "hex": "#474848"}, {"label": "", "spec": "5Y 4/4", "hex": "#6F5F30"}, {"label": "", "spec": "5PB 4/4", "hex": "#51617B"}]}, {"label": "第 4 組", "chips": [{"label": "", "spec": "N 9", "hex": "#E3E3E3"}, {"label": "", "spec": "5Y 9/2", "hex": "#ECE3C3"}, {"label": "", "spec": "LCh 80/30/220", "hex": "#73D4E9"}]}], "ans": ["4"]}, {"id": "L12-5013", "codes": ["L12101", "L12102"], "diff": "中", "level": "應用", "type": "seq", "fam": "hue-order", "ans": ["3", "2", "4", "5", "1"], "stem": "請將下列色票依孟塞爾色相環的順序（R → YR → Y → GY → G → BG → B → PB → P → RP）排列，從最接近紅的開始。請依序輸入五個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "依色相環順序：色票 3（5R 6/6）、色票 2（5Y 7/6）、色票 4（5G 6/4）、色票 5（5PB 7/4）、色票 1（5P 6/6）。", "trap": "明度與彩度略有不同，要只看色相；PB 與 P 的順序最常排錯。", "src": "科目二指引 1.2（孟塞爾色相環）", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5P 6/6", "hex": "#A38AB3"}, {"label": "2", "spec": "5Y 7/6", "hex": "#C2AD5E"}, {"label": "3", "spec": "5R 6/6", "hex": "#C4827E"}, {"label": "4", "spec": "5G 6/4", "hex": "#6B9E85"}, {"label": "5", "spec": "5PB 7/4", "hex": "#9EAFC7"}]}, {"id": "L12-5014", "codes": ["L12201", "L12102"], "diff": "難", "level": "應用", "type": "set", "fam": "tonal-strong", "ans": ["5", "6"], "stem": "系列包裝要讓兩種口味一眼可區分、又維持同一調性。主色的 CIELAB 色相角 h ≈ 96°。要做色相差配色法中的「強色相對比」（同色調、色相角差 120° 以上）。各候選色票的色相角為：色票 1：117°、色票 2：159°、色票 3：63°、色票 4：350°、色票 5：270°、色票 6：220°。請由小到大輸入所有符合的色票編號（數字連寫；張數不一定，請自己判斷）。（本題的「同色調」指 CIELAB 的 L* 與 C* 相近。）【全對全錯】", "explain": "與主色的色相角差（取小於 180° 的那一邊）：270° 差 174°；220° 差 124°；350° 差 106°；159° 差 63°；63° 差 33°；117° 差 21°。差 120° 以上的只有 色票 5（LCh 80/30/270）、色票 6（LCh 80/30/220）。（配色法名稱依官方參考指引：鄰近色配色法 tone in tone、色調差配色法 tone on tone、色相差配色法 tonal。色調以明度與彩度的組合理解，實務上以 CIELAB 的 L* 與 C* 是否相近來判斷。）", "trap": "350° 與 96° 的差要繞過 0°，是 106° 而不是 254°，屬於中色相對比；題目要同時運用色相角計算與對比強度的分級。", "src": "科目二指引 2.3（第 2-34 頁）；科目二指引 1.2（CIELAB 色相角）", "prac": true, "subj": "L12", "dom": "D5", "origin": "115題庫v2", "diag": false, "chips": [{"label": "1", "spec": "5GY 8/4", "hex": "#C2CE95"}, {"label": "2", "spec": "5G 8/4", "hex": "#9FD4B7"}, {"label": "3", "spec": "5YR 8/4", "hex": "#E9C0A2"}, {"label": "4", "spec": "LCh 80/30/350", "hex": "#F8B3D1"}, {"label": "5", "spec": "LCh 80/30/270", "hex": "#A3C9FE"}, {"label": "6", "spec": "LCh 80/30/220", "hex": "#73D4E9"}], "main": {"label": "主色", "spec": "5Y 8/4", "hex": "#D6C891"}}, {"id": "L11-1001", "codes": ["L11104"], "diff": "易", "level": "理解", "stem": "在物體表面的光效應中，下列敘述何者正確？", "opts": ["鏡面反射時反射光的方向不遵守反射定律", "擴散反射會產生物體表面的光澤感", "漫射時反射光線以各種不同角度射出", "光滑表面較容易產生漫射效果"], "explain": "粗糙表面易產生漫射，反射光向各方向散出；光滑表面易產生鏡射，形成光澤。", "trap": "把鏡射與漫射的成因、效果對調。", "src": "科目一指引 1.4（第 2-14～2-15 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1001", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "C"}, {"id": "L11-1002", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "某 LED 產品規格標示演色指數 Ra = 95，這代表什麼意義？", "opts": ["光源的色溫非常接近 6500 K 的標準日光，適合對色", "物體顏色非常接近在同色溫參考光源下的顏色", "光源的發光效率達到 95%，非常節能", "光源的亮度比一般燈具高 95%"], "explain": "Ra 比較待測光源與同色溫參考光源下標準色票的色差，100 為完全一致；Ra ≥ 95 適合對色、攝影等需要忠實呈現色彩的場合。", "trap": "演色性與色溫、發光效率、亮度都是不同指標；Ra 是和同色溫參考光源比較的結果，不代表色溫接近日光。", "src": "科目一指引 1.4（第 2-14 頁）；科目三指引 1.5", "origin": "學生協助命題（115 審修）", "fam": "cri", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L11-1003", "codes": ["L11201"], "diff": "易", "level": "理解", "stem": "在數位影像系統中，色彩深度（color depth）與下列何者關係最密切？", "opts": ["每個像素記錄色彩所用的位元數", "裝置可呈現的色域範圍，色域越大深度越高", "畫面最亮與最暗之間的動態範圍", "感光元件的像素數量與解析度"], "explain": "色彩深度指記錄色彩階調所使用的位元數，位元數越多，可表現的階調越細緻。", "trap": "色域（範圍）與色彩深度（階數）常被混淆。", "src": "科目一指引 2.1（第 2-25～2-26 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1003", "type": "mc", "subj": "L11", "dom": "D3", "diag": false, "ans": "A"}, {"id": "L13-1001", "codes": ["L13102", "L13101"], "diff": "中", "level": "應用", "stem": "某 LED 燈具標示：色溫 6500 K、Ra 92、功率 10 W、照度 1200 lx。下列哪一項資訊無法從這些規格直接得知？", "opts": ["光源的光色（由色溫得知）", "光源的演色特性（由 Ra 得知）", "標示量測條件下的照度（由 lx 得知）", "光源的發光效率（lm/W）"], "explain": "發光效率＝光通量（lm）÷ 電功率（W）。規格只給照度（lx，與量測距離有關），沒有總光通量，無法算出 lm/W。", "trap": "照度與光通量單位不同，不能直接拿來除以功率。", "src": "科目三指引 1.1（第 2-4～2-5 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1001", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1005", "codes": ["L11102"], "diff": "易", "level": "知識", "stem": "視網膜上的感光細胞分為錐狀細胞與桿狀細胞。下列敘述何者錯誤？", "opts": ["錐狀細胞主要集中在中央小窩", "桿狀細胞數量遠多於錐狀細胞", "桿狀細胞無法分辨色彩", "錐狀細胞負責暗視覺"], "explain": "暗視覺由桿狀細胞負責；錐狀細胞在明亮環境下作用，負責色彩視覺。", "trap": "", "src": "科目一指引 1.2", "origin": "學生協助命題（115 審修）", "fam": "rodcone", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1006", "codes": ["L11102"], "diff": "易", "level": "理解", "stem": "某品管人員在色覺測試中無法正確辨識紅色與綠色。下列敘述何者最可能正確？", "opts": ["L 型或 M 型錐狀細胞缺乏或異常", "S 型錐狀細胞缺乏，使紅綠訊號無法互相比較", "桿狀細胞缺乏，在明亮環境下無法分辨紅綠", "視網膜受損，看到的顏色都呈現灰階"], "explain": "第 1、2 型色覺異常分別與 L、M 錐狀細胞有關，都會混淆紅綠；缺 S 是第 3 型；全色盲極罕見。", "trap": "缺 S 錐狀細胞是第 3 型，混淆的是藍與黃；桿狀細胞不負責色覺；全色盲極罕見，也不只是紅綠混淆。", "src": "科目一指引 1.2（第 2-8 頁）", "origin": "學生協助命題（115 審修）", "fam": "cvd", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "A"}, {"id": "L11-1007", "codes": ["L11103"], "diff": "易", "level": "理解", "stem": "關於光的物理特性，下列敘述何者錯誤？", "opts": ["可見光的波長範圍約介於 380 nm 至 780 nm", "光源演色性越低，色彩呈現越接近自然日光", "色光的加法混色適用於螢幕、投影機等以發光方式呈現影像的裝置", "太陽光是熱效應光源，具有接近全光譜的特性"], "explain": "演色性越高才越接近參考光源（日光）下的色彩表現。", "trap": "把演色性的高低方向弄反。", "src": "科目一指引 1.3、1.4", "origin": "學生協助命題（115 審修）", "fam": "L11-1007", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L11-1009", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "凝視某個色相一段時間後轉看白色區域，出現的後像（殘像）會呈現什麼顏色？", "opts": ["與原色相相同的顏色", "原色相的高明度版本", "原色相的心理補色", "與原色相混合的灰色"], "explain": "繼時對比中，後像往心理補色方向出現，與對立色處理機制有關。", "trap": "", "src": "科目一指引 3.3（第 2-49～2-50 頁）", "origin": "學生協助命題（115 審修）", "fam": "after", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1010", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "兩個中高彩度、明度相近的顏色相鄰時產生色滲。要減低色滲，下列何者最有效？", "opts": ["提高兩色的彩度，讓各自的色彩更鮮明", "擴大兩色的接觸面積，使邊界不易察覺", "在兩色之間加入黑色或中性色邊線", "讓兩色的明度更接近，降低邊界的明暗反差"], "explain": "以中性色隔開，可降低同時對比與色滲效果。", "trap": "提高彩度、讓明度更接近，都會讓色滲更嚴重；擴大接觸面積也會讓問題更明顯。", "src": "科目一指引 3.3（第 2-49 頁）", "origin": "學生協助命題（115 審修）", "fam": "bleed", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1011", "codes": ["L11303"], "diff": "易", "level": "理解", "stem": "下列哪一種情況最容易產生色彩同化現象？", "opts": ["大面積的互補色相鄰並置，色彩互相影響", "顏色被切割成極細小的條紋或圖案", "大面積的純色背景襯托小圖形", "相鄰兩色具有強烈的明度對比"], "explain": "相鄰色面積非常細小時，色彩對比會被同化取代，鄰近色互相趨近。", "trap": "同化發生在色彩面積極細小時；大面積並置與強烈明度對比都偏向產生對比效果。", "src": "科目一指引 3.3（第 2-51 頁）", "origin": "學生協助命題（115 審修）", "fam": "assim", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "B"}, {"id": "L11-1012", "codes": ["L11302"], "diff": "易", "level": "應用", "stem": "數位廣告看板要讓關鍵文字在複雜背景中保持清晰可讀，最應優先採用哪一項原則？", "opts": ["使用多種色相，以色相差區隔文字與背景", "運用色彩同化，讓文字與背景更加協調", "提高文字的彩度，使其在背景中更醒目", "確保文字與背景有足夠的明度對比"], "explain": "提高可視度的關鍵是明暗對比，其次是字體尺寸與粗細；只有色相差、沒有明度差的配色可視度差。", "trap": "可視度的關鍵是明度對比；只有色相差或彩度差而缺乏明度差時仍然難讀，同化則會讓文字融入背景。", "src": "科目一指引 3.2（第 2-45 頁）", "origin": "學生協助命題（115 審修）", "fam": "visib", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "D"}, {"id": "L11-1013", "codes": ["L11303"], "diff": "易", "level": "分析", "stem": "長時間注視某色彩後再看白色區域會產生後像。下列哪一個條件「不利於」產生後像？", "opts": ["眼球快速且頻繁地移動", "觀察目標有足夠大的面積", "眼球持續注視固定位置", "刺激物保持穩定的色彩強度"], "explain": "後像需要視網膜接受穩定、持續、面積足夠的刺激；眼球持續移動或面積太小就看不到。", "trap": "", "src": "科目一指引 3.3（第 2-50 頁）", "origin": "學生協助命題（115 審修）", "fam": "after", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "A"}, {"id": "L11-1014", "codes": ["L11303"], "diff": "易", "level": "分析", "stem": "關於色彩對比與色彩同化，下列敘述何者正確？", "opts": ["面積大小是決定產生對比或同化的主要因素之一", "繼時對比是兩色同時並置在視野中所產生的對比", "細密的紋理圖案面積越大，越容易產生色彩對比", "色彩同化多發生在無彩色之間，有彩色較不明顯"], "explain": "相鄰色面積夠大時偏向對比（差異被強化），面積極小時偏向同化（互相趨近）。", "trap": "繼時對比是先後觀看所產生，同時並置的是同時對比；細紋理偏向同化；有彩色與無彩色都會發生同化。", "src": "科目一指引 3.3", "origin": "學生協助命題（115 審修）", "fam": "assim", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "A"}, {"id": "L11-1016", "codes": ["L11205"], "diff": "易", "level": "應用", "stem": "某團隊在提案通過後，打樣一次就直接交付量產，結果量產品在賣場燈光下顏色與提案差異很大。依色彩計畫的實務流程，他們最主要漏掉了哪些階段？", "opts": ["提案階段的色彩趨勢調查", "把設計目標拆解為關鍵字的階段", "選定色彩體系的階段", "打樣後的測試，以及量產後的品管追蹤"], "explain": "色彩計畫實務流程為提案 → 打樣 → 測試 → 品管追蹤，打樣與測試要來回修正，量產後還要與生產部門追蹤加工與使用情境對色彩的影響。這個團隊跳過了測試與品管追蹤。", "trap": "其他選項都是提案或設計階段的工作，與「量產後才出問題」沒有直接關係。", "src": "科目一指引 2.5（第 2-33 頁）；科目二指引 2.1", "origin": "學生協助命題（115 審修）", "fam": "planstep", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "D"}, {"id": "L11-1021", "codes": ["L11301"], "diff": "易", "level": "應用", "stem": "某語言只有黑、白、紅三個基本色名。依跨文化研究的色名發展順序，它接下來最可能發展出哪一個基本色名？", "opts": ["藍", "咖啡色", "黃或綠", "粉紅"], "explain": "依 Berlin & Kay 的跨文化研究，基本色名的發展順序為：黑白 → 紅 → 黃或綠 → 藍 → 棕 → 紫、粉紅、橙、灰。只有黑、白、紅三個色名的語言，下一步是黃或綠；藍在其後，棕更晚，粉紅屬最後階段。", "trap": "", "src": "科目一指引 3.1（第 2-42～2-43 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1021", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1022", "codes": ["L11301"], "diff": "易", "level": "理解", "stem": "關於色彩命名的標準化，下列敘述何者錯誤？", "opts": ["ISCC-NBS 以「色調修飾語＋基本色名」形式命名", "所有文化的色彩命名系統都完全相同", "日本工業標準（JIS）訂有色彩名稱規範", "工商業發展成熟的語言，通常發展出較多色名"], "explain": "各文化的色名發展順序有共通性，但最終色名數量與內容不同。", "trap": "", "src": "科目一指引 3.1（第 2-42 頁）", "origin": "學生協助命題（115 審修）", "fam": "L11-1022", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "B"}, {"id": "L11-1023", "codes": ["L11205", "L12102"], "diff": "中", "level": "應用", "stem": "進行工業產品的色彩規格溝通時，下列哪一種做法最恰當？", "opts": ["提供 RGB 與 CMYK 數值，讓各生產端依數值自行調色", "提供實體標準色樣，並附上 CIELAB 或孟塞爾等色彩標記", "以品牌自訂的色名搭配情境照片，讓供應商理解色彩意象", "以口語化的色彩形容詞描述，並附上螢幕截圖作為參考"], "explain": "色彩計畫要以標準色樣與色彩標記作為生產依據；RGB、CMYK 是裝置相關色，口語與自訂色名缺乏精確性。", "trap": "RGB、CMYK 是裝置相關色，同一組數值在不同裝置上顏色不同；自訂色名、形容詞與螢幕截圖都缺乏精確性。", "src": "科目二指引 2.1（第 2-17 頁）；李文淵簡報（色彩系統分類）", "origin": "學生協助命題（115 審修）", "fam": "deliver", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "B"}, {"id": "L11-1024", "codes": ["L11301", "L11205"], "diff": "難", "level": "分析", "stem": "跨國企業要在不同語言地區推廣同一產品，關於產品色彩的命名與溝通策略，下列何者最適當？", "opts": ["直接翻譯原產地的色名，維持全球一致的品牌語彙", "對內對外都以 RGB 數值描述，避免語言造成的誤解", "內部以色票編號或 CIELAB 值為標準，對外搭配在地化色名", "各地區依在地文化自行命名色彩，並以當地供應商的色票作為生產規格"], "explain": "色名受文化影響，聯想與數量都不同；內部規格要用不受語言影響的標記，對消費者則用在地文化能理解的色名。", "trap": "色名受文化影響，直譯未必有相同聯想；RGB 是裝置相關色；各地自訂規格則失去產品色彩的一致性。", "src": "科目一指引 3.1", "origin": "學生協助命題（115 審修）", "fam": "L11-1024", "type": "mc", "subj": "L11", "dom": "D4", "diag": false, "ans": "C"}, {"id": "L11-1025", "codes": ["L11205"], "diff": "易", "level": "知識", "stem": "關於色彩計畫的四大特性，下列何者錯誤？", "opts": ["系統化主要依靠設計師的直覺經驗", "科學化是依據客觀調查資料進行", "一致化是維持各階段色彩形象的統一", "差異化是突顯設計主體與競品的差異"], "explain": "系統化是指適當運用色彩體系來規劃與管理色彩，而不是依賴直覺。", "trap": "", "src": "科目二指引 2.1（第 2-15 頁）", "origin": "學生協助命題（115 審修）", "fam": "plan4", "type": "mc", "subj": "L11", "dom": "D5", "diag": false, "ans": "A"}, {"id": "L13-1029", "codes": ["L13102"], "diff": "易", "level": "應用", "stem": "兩盞燈的電功率都是 10 W，A 燈光通量 1000 lm、B 燈 600 lm。下列敘述何者正確？", "opts": ["B 燈的發光效率較高（60 lm/W，流明越小越省電）", "兩燈發光效率相同（功率相同，效率就相同）", "A 燈較亮但效率相同（光通量不影響發光效率）", "A 燈的發光效率較高（100 lm/W 對 60 lm/W）"], "explain": "電能發光效率＝光通量 ÷ 輸入電功率：A 為 100 lm/W，B 為 60 lm/W。光通量已依人眼光譜光視效率加權，流明越高，人眼感受的總光量越多。", "trap": "發光效率＝光通量 ÷ 電功率，功率相同時光通量越大效率越高；把「省電」或「功率」誤當成效率是常見錯誤。", "src": "科目三指引 1.1（第 2-4 頁）", "origin": "學生協助命題（115 審修）", "fam": "flux", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L13-1031", "codes": ["L13101"], "diff": "易", "level": "理解", "stem": "LED 光源標示相關色溫（CCT）6500 K，代表什麼？", "opts": ["其光譜分布與 6500 K 黑體輻射相同", "LED 晶片實際工作溫度約為 6500 K", "其光色接近 6500 K 黑體輻射的顏色", "LED 的使用壽命為 6500 小時"], "explain": "相關色溫是在色度圖上最接近該光色的黑體溫度，與燈具實際溫度無關。", "trap": "相關色溫只描述光色（色度），不代表光譜相同，也與燈具實際溫度無關。", "src": "科目三指引 1.2（第 2-10 頁）", "origin": "學生協助命題（115 審修）", "fam": "cct", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "C"}, {"id": "L13-1032", "codes": ["L13102"], "diff": "易", "level": "理解", "stem": "在沒有其他光源干擾的理想情況下，點光源的照度與距離的關係為何？", "opts": ["照度與距離平方成反比", "照度與距離無關", "照度與距離平方成正比", "照度與距離成反比"], "explain": "照度與光源到量測面的距離平方成反比。", "trap": "部分講義誤植為「平方成正比」。", "src": "科目三指引 1.1（第 2-5 頁）", "origin": "學生協助命題（115 審修）", "fam": "illum", "type": "mc", "subj": "L13", "dom": "D1", "diag": false, "ans": "A"}, {"id": "L11-1033", "codes": ["L11103", "L13101"], "diff": "中", "level": "分析", "stem": "關於色溫與演色性的關係，下列敘述何者正確？", "opts": ["色溫越高，演色性必定越好", "演色性高的光源，色溫一定高於 5000 K", "高演色性的光源，色溫一定低於 3000 K", "色溫與演色性是兩個獨立的光源特性"], "explain": "色溫描述光色偏黃或偏藍，演色性描述光源呈現物體顏色的忠實程度，兩者分別指定。", "trap": "", "src": "科目一指引 1.3、1.4；科目三指引 1.5", "origin": "學生協助命題（115 審修）", "fam": "lightspec", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "D"}, {"id": "L11-1034", "codes": ["L11103", "L11104"], "diff": "中", "level": "應用", "stem": "某展覽館需要「高演色性且色溫接近自然日光」的光源，下列哪一個最符合？", "opts": ["Ra 75、6500 K 的 LED", "Ra 95、5500 K 的 LED", "Ra 95、2700 K 的 LED", "Ra 75、5500 K 的 LED"], "explain": "兩個條件要同時滿足：演色性高（Ra ≥ 90），且色溫接近日光（約 5000–6500 K）。", "trap": "", "src": "科目一指引 1.3、1.4", "origin": "學生協助命題（115 審修）", "fam": "lightspec", "type": "mc", "subj": "L11", "dom": "D1", "diag": false, "ans": "B"}, {"id": "L13-1035", "codes": ["L13104"], "diff": "易", "level": "知識", "stem": "使用分光光度儀量測表面色之前，通常需要進行哪一種校正？", "opts": ["黑歸零校正（光源色量測）", "高光澤黑玻璃校正", "藍板校正", "白板校正"], "explain": "表面色量測以白板校正，取得光譜反射率；光源色量測用黑歸零；光澤計用高光澤黑玻璃。", "trap": "", "src": "科目三指引 2.1（第 2-31、2-37 頁）", "origin": "學生協助命題（115 審修）", "fam": "calib", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "D"}, {"id": "L13-1036", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "要量測白光 LED 這類光譜中有尖峰的光源，取得精細的光譜功率分布，分光元件與取樣間隔應如何選擇？", "opts": ["使用繞射光柵等精細分光元件，取樣間隔 5 nm 或更細", "使用寬頻濾鏡的色度計即可，取樣間隔不影響結果", "使用 10 nm 以上的取樣間隔即可，與物體色相同", "使用光澤計量測"], "explain": "光源可能有窄頻帶成分，需要較精細的分光（目前多用繞射光柵）並以 5 nm 或更細的間隔取樣；物體反射率曲線較平滑，10 nm 間隔即可。寬頻濾鏡無法取得精細光譜。", "trap": "把物體色的取樣條件套用到光源。", "src": "科目三指引 2.1（第 2-31 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1036", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "A"}, {"id": "L13-1037", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "下列哪一種色彩量測不需要儀器提供照明光源？", "opts": ["表面色量測", "透明色（穿透色）量測", "光源色量測", "反射率量測"], "explain": "光源色量測的對象本身就會發光；表面色與穿透色都要由儀器提供照明再量測反射或透射。", "trap": "", "src": "科目三指引 2.1（第 2-31 頁）", "origin": "學生協助命題（115 審修）", "fam": "L13-1037", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "C"}, {"id": "L13-1038", "codes": ["L13303"], "diff": "易", "level": "理解", "stem": "色彩管理系統中的色彩描述檔（ICC profile）主要定義了什麼關係？", "opts": ["裝置色彩空間與 sRGB 標準色彩空間之間的對應", "裝置色彩空間與 CIE 色度系統之間的對應", "色光三原色與色料三原色之間的混色對應", "物體光譜反射率與光源色溫之間的對應"], "explain": "描述檔記錄裝置訊號與裝置無關色度值（XYZ 或 LAB）的對應，是轉換的依據。", "trap": "描述檔對應的是裝置無關的 CIE 色度值（XYZ 或 LAB），不是 sRGB 這類 RGB 規格。", "src": "科目一指引 2.6；科目三指引 2.3", "origin": "學生協助命題（115 審修）", "fam": "L13-1038", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "B"}, {"id": "L13-1039", "codes": ["L13204"], "diff": "易", "level": "應用", "stem": "相機以「灰色世界法」做自動白平衡。拍攝下列哪一種畫面時，最容易修錯顏色？", "opts": ["畫面大部分是一大片綠色草地", "色彩分布均勻、各色都有的街景", "有白牆與灰色地面的室內場景", "包含灰卡與多色商品的商品照"], "explain": "灰色世界法假設整張影像的平均色是灰色。畫面被單一顏色佔滿時平均不是灰，系統會誤把草地的綠當成偏色而往洋紅方向修正。", "trap": "", "src": "科目三指引 2.3（第 2-44～2-45 頁）", "origin": "學生協助命題（115 審修）", "fam": "wb", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "A"}, {"id": "L13-1040", "codes": ["L13205", "L13302", "L13303"], "diff": "難", "level": "分析", "stem": "印刷廠要印製產品型錄，封面與內頁由不同人製作。為了確保整本色彩一致，下列哪一種做法最合適？", "opts": ["依 ISO 12647-2 校準印刷條件，封面與內頁各自選用不同的 CMYK 描述檔", "依 ISO 12647-2 校準印刷條件，以相符描述檔在同一流程中轉換", "封面與內頁各自依經驗調色，再以印刷機預設值統一輸出", "封面改以 RGB 直接輸出，內頁用 CMYK，以兼顧鮮豔與一致"], "explain": "一致性來自同一套標準：校準到印刷規範、以相符描述檔做特性描述與轉換。", "trap": "只校準印刷條件還不夠，封面與內頁要用同一個相符描述檔轉換；各自依經驗或改用 RGB 都會破壞一致性。", "src": "科目三指引 2.3（第 2-43 頁）；徐明景簡報", "origin": "學生協助命題（115 審修）", "fam": "L13-1040", "type": "mc", "subj": "L13", "dom": "D7", "diag": false, "ans": "B"}, {"id": "L13-1041", "codes": ["L13104"], "diff": "易", "level": "理解", "stem": "某印刷廠量測樣品時使用 d/8°（SPEX）幾何條件，下列敘述何者正確？", "opts": ["8° 方向照明，擴散觀測，含鏡面反射", "擴散照明，8° 方向觀測，含鏡面反射", "8° 方向照明，擴散觀測，不含鏡面反射", "擴散照明，8° 方向觀測，不含鏡面反射"], "explain": "斜線前為照明、後為觀測；d 為擴散（積分球）；SPEX 為 specular excluded。", "trap": "", "src": "科目三指引 2.1（第 2-35 頁）", "origin": "學生協助命題（115 審修）", "fam": "spex", "type": "mc", "subj": "L13", "dom": "D6", "diag": false, "ans": "D"}, {"id": "L13-6001", "codes": ["L13104", "L13101"], "diff": "易", "level": "理解", "fam": "calib", "stem": "要量測 LED 舞台燈的光譜功率分布與色溫，下列儀器與使用前步驟的搭配何者正確？", "opts": ["分光光度儀，使用前以白板校正", "濃度計，使用前以印刷紙白歸零後再量", "分光輻射儀，使用前遮光做黑歸零", "光澤計，使用前以黑玻璃校正"], "explain": "燈具是光源色，要量進入儀器的光，用分光輻射儀並先做黑歸零。分光光度儀自帶光源、量物體反射率，適用表面色。", "trap": "把「白板校正」套到所有儀器，是 D-16 最常見的錯誤。", "src": "科目三指引 2.1–2.2（第 2-31～2-41 頁）", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L13-6002", "codes": ["L13104", "L13103"], "diff": "中", "level": "理解", "fam": "calib", "stem": "品管人員只有一台三刺激值型色度計，想判斷兩塊布在 D65 與 A 光源下是否會出現同色異譜。下列判斷何者正確？", "opts": ["色度計先以白板校正後，就能輸出完整的光譜反射率", "色度計沒有光譜反射率，無法換光源重算，應改用分光光度儀量測", "只要兩塊布在 D65 下 ΔE 小於 1，任何光源都不會異譜", "色度計換成 10° 觀察者設定，即可模擬 A 光源"], "explain": "同色異譜是光譜不同、在某光源下三刺激值相同。要判斷換光源後是否仍相同，需要 ρ(λ)，再分別帶入 D65 與 A 的光譜計算；色度計只有三個濾片的輸出，做不到。", "trap": "觀察者（2°／10°）與光源是兩件事，常被混為一談。", "src": "科目三指引 2.1–2.2（第 2-31～2-41 頁）", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6003", "codes": ["L13104", "L13207"], "diff": "難", "level": "分析", "fam": "calib", "stem": "包裝印刷廠一天要完成四件量測：（甲）看樣燈箱光源的光譜與色溫、（乙）印刷色塊的 L*a*b*、（丙）油墨的反射濃度、（丁）上光後的表面光澤。下列儀器與校正的搭配何者正確？", "opts": ["甲 分光光度儀（白板）；乙 分光輻射儀（黑歸零）；丙 濃度計；丁 光澤計（黑玻璃）", "甲 分光輻射儀（黑歸零）；乙 濃度計（紙白）；丙 光澤計；丁 分光光度儀（白板）", "甲 分光輻射儀（黑歸零）；乙 分光光度儀（白板）；丙 濃度計；丁 光澤計（黑玻璃）", "甲 色度計（白板）；乙 分光光度儀（黑玻璃）；丙 光澤計；丁 濃度計（紙白）"], "explain": "光源色用分光輻射儀（黑歸零）；表面色用分光光度儀（白板校正）；反射濃度 D = log(1/R) 用濃度計；光澤用光澤計，以高光澤黑玻璃標準板定義 100 GU。", "trap": "儀器要跟著「量什麼」走：發光、反射、濃度、光澤各有對應儀器與基準。", "src": "科目三指引 2.1–2.2（第 2-31～2-41 頁）", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L13-6004", "codes": ["L12102", "L13105"], "diff": "易", "level": "應用", "fam": "lch", "stem": "某色 CIELAB = (50, 30, −30)，換成 L*C*h 表示，下列何者正確？", "opts": ["C* ≈ 42.4，h = 315°", "C* ≈ 42.4，h = −45°", "C* = 0，h = 315°", "C* = 60，h = 135°"], "explain": "C* = √(30² + 30²) ≈ 42.4。a* 為正、b* 為負，在第四象限，h = 360° − 45° = 315°，介於藍與紅之間。", "trap": "計算機的 tan⁻¹(−30/30) 會給 −45°，色相角要換算到 0～360°；60 是把 a*、b* 直接相加。", "src": "科目三指引 1.5；科目二指引 1.2", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6005", "codes": ["L12102", "L13105"], "diff": "中", "level": "應用", "fam": "lch", "stem": "某青藍色 CIELAB = (70, −20, −20)。換成 L*C*h 後，下列何者正確？", "opts": ["C* ≈ 28.3，h = 45°，位於紅與黃之間", "C* = −28.3，h = 225°，位於綠與藍之間", "C* ≈ 28.3，h = 135°，位於黃與綠之間", "C* ≈ 28.3，h = 225°，位於綠與藍之間"], "explain": "C* = √(400 + 400) ≈ 28.3，彩度不會是負值。a*、b* 皆為負，屬第三象限，h = 180° + 45° = 225°，在綠（約 180°）與藍（約 270°）之間。", "trap": "tan⁻¹(−20/−20) = tan⁻¹(1) = 45°，若不補象限就會誤判為紅黃之間。", "src": "科目三指引 1.5；科目二指引 1.2", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6006", "codes": ["L12102", "L13105"], "diff": "難", "level": "分析", "fam": "lch", "stem": "包裝需要一個「黃色、且 C* 至少 50」的主色。下列四個候選色（L*, a*, b*）中，哪一個同時符合兩個條件？", "opts": ["(85, 30, 30)", "(80, −40, 40)", "(75, 0, 45)", "(80, 5, 60)"], "explain": "(80, 5, 60)：C* ≈ 60.2，h ≈ 85°，接近黃（90°）。(85, 30, 30)：h = 45°，屬橙；(80, −40, 40)：h = 135°，屬黃綠；(75, 0, 45)：h = 90° 是正黃，但 C* = 45 未達 50。", "trap": "只看色相或只看彩度都會選錯，要兩個條件一起算。", "src": "科目三指引 1.5；科目二指引 1.2", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6007", "codes": ["L13105"], "diff": "易", "level": "應用", "fam": "deltaE", "stem": "標準色 CIELAB = (40, −10, 20)，樣品 = (42, −14, 20)。下列何者正確？", "opts": ["樣品較暗、偏紅，ΔE*ab ≈ 4.5", "樣品較亮、偏綠，ΔE*ab = 6", "樣品較亮、偏綠，ΔE*ab ≈ 4.5", "樣品較亮、偏黃，ΔE*ab = 20"], "explain": "ΔL* = +2（較亮）、Δa* = −4（往 −a* 偏綠）、Δb* = 0；ΔE*ab = √(4 + 16) = √20 ≈ 4.5。", "trap": "6 是把差值直接相加，20 是忘了開根號；差值一律是「樣品 − 標準」。", "src": "科目三指引 1.5、2.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L13-6008", "codes": ["L13105", "L12102"], "diff": "中", "level": "分析", "fam": "deltaE", "stem": "標準色 = (60, 20, 30)，樣品 = (60, 26, 39)，ΔE*ab ≈ 10.8。若要向調色師說明差異，下列描述何者最正確？", "opts": ["主要是色相往紅偏，因為 Δa* 為正", "主要是彩度變高，色相角幾乎沒有改變", "主要是色相往黃偏，因為 Δb* 最大", "主要是明度變化，因為 ΔE 很大"], "explain": "標準 C* ≈ 36.1、樣品 C* ≈ 46.9，ΔC* ≈ +10.8；兩者 b*/a* 都是 1.5，h 都約 56.3°，所以 ΔH* ≈ 0。整個色差幾乎都是彩度差。", "trap": "Δa*、Δb* 同時為正，不代表色相偏移；要換成 ΔL*、ΔC*、ΔH* 才看得出方向。", "src": "科目三指引 1.5、2.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6009", "codes": ["L13105", "L12102"], "diff": "難", "level": "應用", "fam": "deltaE", "stem": "標準色 = (55, 5, 25)，量產樣品 = (52, 8, 21)。要給調色師的修正方向，下列何者正確？", "opts": ["調亮、減少紅、增加黃", "調暗、增加紅、減少黃", "調亮、增加綠、增加藍", "只需調亮，因為明度差最大"], "explain": "ΔL* = −3（偏暗）、Δa* = +3（偏紅）、Δb* = −4（偏藍、黃不足），ΔE*ab = √34 ≈ 5.8。修正要與偏差反向：調亮、減紅、加黃。三個差值中 |Δb*| 最大，不是明度。", "trap": "把樣品的偏差方向直接當成修正方向，是方向題最常見的錯。", "src": "科目三指引 1.5、2.2；科目二指引 1.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6010", "codes": ["L13105", "L13103"], "diff": "易", "level": "理解", "fam": "dh", "stem": "關於色相角差 Δh 與色相差 ΔH* 的敘述，下列何者正確？", "opts": ["ΔH* 與 Δh 的數值永遠相同", "同樣的 Δh，彩度越低，ΔH* 越大", "ΔH* 只和明度差 ΔL* 有關", "同樣的 Δh，彩度越低，ΔH* 越小"], "explain": "ΔH* = 2√(C*₁C*₂)·sin(Δh/2)，會隨彩度縮放。近灰色的色相角可以差很多，但實際色相差很小。", "trap": "把角度當距離，是官方指引特別點出的觀念。", "src": "科目三指引 1.5、2.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6011", "codes": ["L13105", "L13103"], "diff": "中", "level": "分析", "fam": "dh", "stem": "兩組色樣明度相同。甲組兩色 C* 都是 5，色相角差 Δh = 20°；乙組兩色 C* 都是 50，Δh = 4°。哪一組的色相差 ΔH* 較大？", "opts": ["甲組較大，因為色相角差 20° 比 4° 大", "兩組相同，因為兩組都只有色相改變", "乙組較大（約 3.5，甲組約 1.7）", "缺少 L* 數值，無法比較"], "explain": "甲：2 × 5 × sin10° ≈ 1.7；乙：2 × 50 × sin2° ≈ 3.5。高彩度色只轉一點角度，色相差反而較大。", "trap": "直覺以角度大小判斷色相差。", "src": "科目三指引 1.5、2.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L13-6012", "codes": ["L13105", "L13206"], "diff": "難", "level": "分析", "fam": "dh", "stem": "客戶規定灰色布 ΔE*ab ≤ 2.0 即合格。標準 = (60, 1.0, 0)，樣品 = (60, 0.5, 0.87)，報表顯示 Δh ≈ 60°。業務認為「色相角差 60°，一定不合格」。下列判斷何者正確？", "opts": ["不合格：Δh 超過 30°，代表色相偏差過大，應退回重染", "合格：ΔE*ab ≈ 1.0，Δh 大是因為彩度只有約 1", "不合格：灰色布應改以 Δh 評等，ΔE*ab 並不適用", "無法判斷：近灰色的色相角很不穩定，無法計算 ΔE*ab"], "explain": "兩色 C* 都約 1.0，ΔL* = 0、ΔC* ≈ 0，ΔE*ab = √(0.25 + 0.76) ≈ 1.0，也等於 ΔH* = 2 × 1 × sin30°。數值在允差內，Δh 大只是低彩度的現象。", "trap": "與 D-19 同一觀念，換成「允差判定」的情境。", "src": "科目三指引 1.5、2.2", "type": "mc", "subj": "L13", "dom": "D6", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6013", "codes": ["L13305"], "diff": "易", "level": "應用", "fam": "intent", "stem": "公司年報中的長條圖與圓餅圖要由 RGB 轉為 CMYK，希望各色保持鮮明、容易區分，明度或色相略有改變可以接受。應選哪一種演色意圖？", "opts": ["飽和度式", "感應式", "相對色度式", "絕對色度式"], "explain": "飽和度式以保持飽和度為優先，明度與色相可能改變，適用商業圖案或圖表。感應式適用自然影像；兩種色度式適用打樣。", "trap": "", "src": "科目一指引 2.6（第 2-35～2-37 頁）；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6014", "codes": ["L13305", "L13205"], "diff": "中", "level": "理解", "fam": "proofwhite", "stem": "打樣機用紙的紙白比正式印刷的新聞紙白很多。依官方參考指引，要讓打樣與印刷的色度值以各自紙白為基準相對一致，應選哪一種演色意圖？", "opts": ["絕對色度式：以絕對參考白計算，假設紙白相同", "感應式：整體壓縮色域，保持色彩間的關係", "飽和度式：優先保持鮮豔度，明度與色相都可能改變", "相對色度式：以各載體的參考白作為相對計算基準"], "explain": "指引：相對色度公制式以不同載體的參考白作相對計算，適用紙白不相同時的印刷打樣；絕對色度公制式以絕對參考白計算，適用紙白相同時的印刷打樣。", "trap": "兩種色度式的差別在「參考白」，不在色域大小。", "src": "科目一指引 2.6（第 2-35～2-37 頁）；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6015", "codes": ["L13305", "L13205", "L11206"], "diff": "難", "level": "分析", "fam": "intent", "stem": "出版社同時處理三份檔案：（甲）攝影集內頁的風景照、（乙）市場報告的彩色圖表、（丙）與正式印刷使用相同紙張的合約打樣。依官方參考指引，演色意圖的搭配何者最合適？", "opts": ["甲 飽和度式；乙 感應式；丙 相對色度式", "甲 感應式；乙 相對色度式；丙 飽和度式", "甲 感應式；乙 飽和度式；丙 絕對色度式", "甲 絕對色度式；乙 飽和度式；丙 感應式"], "explain": "自然影像用感應式整體壓縮色域；商業圖表用飽和度式保持鮮明；紙白相同的打樣依指引用絕對色度式。", "trap": "照片很鮮豔就選飽和度式，是常見的直覺錯誤。", "src": "科目一指引 2.6（第 2-35～2-37 頁）；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L13-6016", "codes": ["L13303"], "diff": "易", "level": "知識", "fam": "pcs", "stem": "ICC 色彩管理架構中，描述檔連結空間（PCS）採用的是哪一種色彩空間？", "opts": ["D50 的 CIELAB", "D65 的 sRGB 色彩空間", "印刷用的 CMYK", "各台螢幕各自的 RGB"], "explain": "ICC 採用 D50 的 CIELAB 作為 PCS。PCS 必須是裝置無關的色彩空間，才能當作各裝置之間的共同中介。", "trap": "sRGB 雖是標準，但仍是 RGB 裝置空間。", "src": "科目三指引 2.3（第 2-44 頁）；科目一指引 2.6", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6017", "codes": ["L13302", "L13303"], "diff": "中", "level": "理解", "fam": "assign", "stem": "設計師開啟一張嵌入 Adobe RGB 描述檔的照片，卻用「指定描述檔」把它改成 sRGB。下列結果何者正確？", "opts": ["RGB 數值經 PCS 換算，顏色外觀維持不變", "RGB 數值不變，改以 sRGB 解讀，看起來較灰淡", "RGB 數值被裁切到 sRGB 色域，但畫面看起來一樣", "檔案會自動轉成 CMYK，並以印刷色域重新解讀"], "explain": "「指定」只改變數值的解讀方式，同一組數值在色域較小的 sRGB 中代表較不飽和的顏色；「轉換」才會經 PCS 換算數值、盡量維持外觀。", "trap": "指定（assign）與轉換（convert）的差別，是實務最常出錯的步驟。", "src": "徐明景簡報（Photoshop 實務應用）；科目一指引 2.6", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6018", "codes": ["L13304", "L13302"], "diff": "難", "level": "分析", "fam": "3c", "stem": "新購螢幕要用於印刷的軟式打樣。下列工作順序何者正確？", "opts": ["量測色塊建立描述檔 → 校正白點、亮度與階調 → 依描述檔轉換顯示", "校正白點、亮度與階調 → 量測色塊建立描述檔 → 依描述檔轉換顯示", "依描述檔轉換顯示 → 校正白點、亮度與階調 → 量測色塊建立描述檔", "建立一次描述檔即可，之後不必校正，因為螢幕不會隨時間漂移"], "explain": "3C 順序為校正（calibration）→ 特性描述（characterization）→ 轉換（conversion）。特性描述的前提是裝置已校正並穩定；顯示器會老化漂移，需定期重做校正與特性描述。", "trap": "先建描述檔再校正，描述檔描述的就不是校正後的狀態。", "src": "科目一指引 2.6；科目三指引 2.3；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6019", "codes": ["L13306"], "diff": "易", "level": "知識", "fam": "gamut", "stem": "下列 RGB 色彩空間的色域大小排序，何者正確？", "opts": ["sRGB ＞ Adobe RGB ＞ Rec.2020", "Adobe RGB ＞ Rec.2020 ＞ sRGB", "三者色域相同，只差在白點", "Rec.2020 ＞ Adobe RGB ＞ sRGB"], "explain": "Rec.2020 的色域大於 Adobe RGB，Adobe RGB 又大於 sRGB；sRGB 是網頁的預設色彩空間。", "trap": "", "src": "科目二指引 2.4（第 2-41 頁）", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6020", "codes": ["L13306", "L13203"], "diff": "中", "level": "應用", "fam": "deliver2", "stem": "攝影師以 Adobe RGB 完成一組作品，要同時交給電商網站與高品質畫冊印刷。下列做法何者最合理？", "opts": ["保留 Adobe RGB 母檔，網站版轉 sRGB，畫冊依印刷描述檔轉換", "全部先轉成 sRGB，網站與畫冊共用同一個 sRGB 檔案", "全部先轉成 CMYK 作為母檔，網站版再從 CMYK 轉回 RGB 使用", "網站與畫冊都直接使用 Adobe RGB 檔，不需另外轉換"], "explain": "母檔保留較大色域；網頁環境以 sRGB 解讀，所以網站版要轉 sRGB；印刷依實際印刷條件的描述檔轉換。先轉成小色域會永久失去色彩資訊。", "trap": "", "src": "科目二指引 2.4；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6021", "codes": ["L13306", "L13302"], "diff": "難", "level": "分析", "fam": "srgb", "stem": "同一張嵌入 Adobe RGB 描述檔的照片，在 Photoshop 中顏色正常，在某個簡易看圖程式中卻明顯偏灰。最可能的原因是？", "opts": ["看圖程式在開檔時把照片轉成了 CMYK 色彩", "照片在 Photoshop 存檔時已被裁切色域", "看圖程式忽略嵌入描述檔，當成 sRGB 解讀", "螢幕在執行看圖程式時，自動降低了亮度與對比"], "explain": "沒有色彩管理的程式不讀嵌入描述檔，Adobe RGB 的數值被當成 sRGB 顯示，看起來較不飽和。要給一般環境使用的檔案，應先轉成 sRGB。", "trap": "", "src": "科目二指引 2.4；徐明景簡報", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L12-6001", "codes": ["L12201"], "diff": "易", "level": "理解", "fam": "area", "stem": "海報要用 5PB 3/4（深藍）與 5Y 8/12（鮮黃）兩色搭配。依孟塞爾「色彩強度與面積成反比」原則，哪一個顏色應占較大面積？", "opts": ["深藍：明度×彩度較小（12 對 96）", "鮮黃：明度與彩度都高，大面積才夠亮眼醒目", "兩色各半：互補色要等面積才平衡", "鮮黃：彩度較高，要讓它多被看見"], "explain": "強度＝明度×彩度：深藍 3×4＝12，鮮黃 8×12＝96。強度越弱的顏色面積越大，深藍約為鮮黃的 8 倍。", "trap": "以「想讓誰被看見」決定面積，方向剛好相反。", "src": "科目二指引 2.2（第 2-21 頁）", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L12-6002", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "fam": "area", "stem": "包裝底色為 5B 3/4，設計師希望底色與點綴色的面積約為 6：1 並保持平衡。依孟塞爾面積平衡原則，下列哪一個點綴色最合適？", "opts": ["5R 4/12", "5YR 7/8", "5R 6/12", "5Y 8/6"], "explain": "底色強度 3×4＝12，面積比 6：1，點綴色強度需約 12×6＝72。5R 6/12＝72 符合；5R 4/12＝48、5YR 7/8＝56、5Y 8/6＝48 都不夠。", "trap": "要先讀懂孟塞爾標記 H V/C，再反推所需強度；只看彩度最高或明度最高都會選錯。", "src": "科目二指引 2.2（第 2-21 頁）", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L12-6003", "codes": ["L12201", "L13307", "L12102"], "diff": "難", "level": "分析", "fam": "area", "stem": "咖啡店牆面以 5B 3/4 為大面積底色、招牌色 5R 5/12 為點綴，依孟塞爾原則規劃面積比 5：1。客戶以 5 cm 色票確認，漆滿整面牆後卻覺得底色「太鮮、太亮」。下列解釋與調整何者最恰當？", "opts": ["量測 ΔE 很小，代表色票與牆面相同，屬心理作用，維持原設計", "面積效果使大面積更亮更鮮；改 5B 3/3，面積比約調為 6.7：1", "面積越大看起來越暗，應把底色提高到 5B 4/6 來補償", "改 5B 3/3 後底色強度變小，所以面積比也要縮小到約 3.8：1"], "explain": "同一色度值在大面積時看起來更亮、更鮮（面積效果），CIELAB 色差不處理面積，所以 ΔE 小仍可能看起來不同。底色降為 5B 3/3，強度 9；招牌強度 60，平衡面積比＝60/9≈6.7：1。強度變弱，面積應更大，不是更小。", "trap": "結合色彩感覺（面積效果）、色外貌與面積平衡計算；3.8：1 是把反比當正比的誘答。", "src": "科目二指引 2.2（第 2-21 頁）；吳瑞卿簡報（CIECAM02 考慮因素）", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L12-6101", "codes": ["L12101"], "diff": "易", "level": "應用", "type": "seq", "fam": "light-order", "ans": ["4", "1", "2", "3"], "stem": "下列 4 張色票的色相各不相同。請只依「明度」由低到高排列。請依序輸入四個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "明度依序：色票 4（5P 2/4）、色票 1（5B 4/4）、色票 2（5R 6/8）、色票 3（5Y 8/6）。只看明暗，不管色相與彩度。", "trap": "明度間隔 2 級，屬單一主題的基本判斷。", "src": "科目二指引 1.1–1.2、2.3", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "chips": [{"label": "1", "spec": "5B 4/4", "hex": "#356776"}, {"label": "2", "spec": "5R 6/8", "hex": "#D17B77"}, {"label": "3", "spec": "5Y 8/6", "hex": "#DCC876"}, {"label": "4", "spec": "5P 2/4", "hex": "#3D2945"}]}, {"id": "L12-6102", "codes": ["L12101", "L11302"], "diff": "中", "level": "應用", "fam": "visib2", "stem": "包裝背景為 5Y 8/10（亮黃），要在上面放成分說明的小字。候選字色為 5PB 3/8、5R 5/12、5G 7/6、5YR 8/6。依「明度差越大、可視度越高」的原則，哪一個最適合？", "opts": ["5R 5/12：彩度最高，最醒目", "5G 7/6：色相與黃色差距較大", "5YR 8/6：色相接近，畫面最協調", "5PB 3/8：與背景明度差 5 級"], "explain": "可視度主要由明度差決定。背景明度 8：5PB 3/8 差 5 級、5R 5/12 差 3 級、5G 7/6 差 1 級、5YR 8/6 差 0。小字要清楚，選明度差最大的深藍。", "trap": "把「鮮豔」或「色相差大」當成清楚；結合色彩學的可視度與計畫實務的明度判斷。", "src": "科目一指引 3.2（可視度）；科目二指引 1.1–1.2、2.3", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L12-6103", "codes": ["L12101", "L11302", "L13105"], "diff": "難", "level": "分析", "fam": "visib2", "stem": "網頁按鈕底色為 CIELAB L* = 40 的藍。文字色有三案：白（L* = 95）、鮮黃（L* = 85，C* = 80）、洋紅（L* = 55，C* = 70）。業務主張「洋紅最鮮豔，所以最醒目」。依明度差判斷文字可視度，下列何者正確？", "opts": ["白＞黃＞洋紅；洋紅與底色明度只差 15", "洋紅＞黃＞白；彩度越高的文字越清楚", "黃＞白＞洋紅；黃色看起來永遠最亮", "三者都相同；都和藍色底形成明顯的色相對比"], "explain": "明度差：白 55、黃 45、洋紅 15。可視度以明度差為主，洋紅雖然 C* 最高，與底色的明度差最小，小字最難讀。", "trap": "把彩度（鮮豔）與明度（明暗）混為一談；要能從 CIELAB 數值分開讀出 L* 與 C*。", "src": "科目一指引 3.2；科目三指引 1.5", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L12-6104", "codes": ["L12201"], "diff": "易", "level": "理解", "fam": "scheme-pick", "stem": "主色為 5PB 5/6。下列哪一組搭配屬於「色調差配色法」（同色相、不同色調）？", "opts": ["5B 5/6 與 5P 5/6", "5PB 8/2 與 5PB 3/8", "5R 5/6 與 5Y 5/6", "N 8 與小面積的 5PB 5/6"], "explain": "色調差配色法：色相相同，明度、彩度拉開。5B 與 5P 是色相相鄰、色調相同（鄰近色配色法）；5R 與 5Y 是色調相同、色相差大（色相差配色法）；N 8 為無彩配有彩。", "trap": "四個選項分別對應四種配色法。", "src": "科目二指引 2.3（第 2-33 頁）", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L12-6105", "codes": ["L12201", "L12102"], "diff": "中", "level": "應用", "fam": "scheme-pick", "stem": "主色為 LCh (70, 40, 250)。要做「色相差配色法」（同色調、色相差大），本課以 CIELAB 的 L*、C* 是否相近判斷色調。下列哪一個候選色最合適？", "opts": ["LCh (40, 40, 250)", "LCh (70, 40, 220)", "LCh (70, 40, 70)", "LCh (72, 10, 70)"], "explain": "(70, 40, 70)：L*、C* 相同，色相差 180°，符合。(40, 40, 250) 同色相、明度不同，是色調差配色法；(70, 40, 220) 色相只差 30°，是鄰近色配色法；(72, 10, 70) 色相差大，但 C* 差 30，色調不同。", "trap": "只看色相差而忽略 C*，會誤選 (72, 10, 70)。", "src": "科目二指引 2.3；科目三指引 1.5", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L12-6106", "codes": ["L12201", "L13105", "L12102"], "diff": "難", "level": "分析", "fam": "scheme-qc", "stem": "提案採「鄰近色配色法」，三色 LCh 為 (65, 35, 40)、(64, 36, 60)、(66, 34, 80)。打樣後量得第三色為 (66, 50, 80)。下列判斷何者正確？", "opts": ["色相角沒有改變，所以配色法不受影響，可直接進入量產", "ΔE ≈ 16 主要來自色相偏移，應先調整色相角後再重新打樣", "這是同色異譜造成，只要換到標準光源下觀看就會一致", "C* 升為 50，ΔE ≈ 16 全為彩度差，已非同色調"], "explain": "L* 與 h 不變，ΔC* = 16，ΔE*ab = 16，全是彩度差。鄰近色配色法要求色調相近，第三色變鮮後與另兩色不再同色調，打樣應以降低彩度修正。", "trap": "結合配色法定義與色差判讀：h 沒變不代表配色成立。", "src": "科目二指引 2.3；科目三指引 1.5、2.2", "type": "mc", "subj": "L12", "dom": "D5", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L12-6107", "codes": ["L12101"], "diff": "易", "level": "應用", "type": "seq", "fam": "hue-order", "ans": ["1", "2", "4", "3"], "stem": "以 R 為起點，請將下列色票依孟塞爾色相環 R → YR → Y → GY → G → BG → B → PB → P → RP 的方向排列。請依序輸入四個色票編號（數字連寫，不加空格）。【全對全錯】", "explain": "由 R 起依序：色票 1（5YR 6/8）（YR）、色票 2（5GY 7/6）（GY）、色票 4（5B 6/6）（B）、色票 3（5RP 5/8）（RP）。", "trap": "RP 在 P 與 R 之間，從 R 出發時排在最後。", "src": "科目二指引 1.2（孟塞爾色相環）", "prac": true, "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "chips": [{"label": "1", "spec": "5YR 6/8", "hex": "#CA834B"}, {"label": "2", "spec": "5GY 7/6", "hex": "#A2B667"}, {"label": "3", "spec": "5RP 5/8", "hex": "#AF6180"}, {"label": "4", "spec": "5B 6/6", "hex": "#4B9EB3"}]}, {"id": "L12-6108", "codes": ["L12102", "L11105", "L13105"], "diff": "中", "level": "理解", "fam": "hue-lab", "stem": "某黃色的 CIELAB 色相角 h ≈ 95°。若要找它的對比色（h 加 180°），大約落在孟塞爾色相環的哪一區？", "opts": ["G（綠）附近", "R（紅）附近", "PB（紫藍）附近", "YR（黃紅）附近"], "explain": "95° + 180° = 275°，在 CIELAB 中位於藍到紫藍之間，對應孟塞爾的 PB 附近。孟塞爾色相與 CIELAB 色相角並非等距對應，只能大致換算。", "trap": "結合 CIELAB 色相角與孟塞爾色相環；G 約 150–170°，R 約 20–40°。", "src": "科目二指引 1.2；科目三指引 1.5", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}, {"id": "L11-6101", "codes": ["L11303", "L12101"], "diff": "難", "level": "分析", "fam": "simcon", "stem": "包裝以大面積 5R 5/12 紅色為底，中央放一塊小面積 5Y 7/8 黃色標籤。消費者覺得標籤「偏綠」。依同時對比與孟塞爾色相環，下列解釋何者正確？", "opts": ["紅色滲入黃色標籤（同化），使黃往 YR 方向偏", "黃色標籤在印刷時，油墨被印成了偏綠的顏色", "人眼對黃色較不敏感，所以看起來偏綠一些", "被加上背景紅的補色（BG）傾向，往 GY 偏"], "explain": "同時對比使圖色往背景的補色方向偏移。紅的補色在 BG，黃加上 BG 傾向，在色相環上往 GY 移動，所以看起來偏綠。往 YR 偏是細紋路才會出現的同化現象。", "trap": "同時對比與色彩同化方向相反；要用色相環說出偏移方向。", "src": "科目一指引 3.3（同時對比）；科目二指引 1.2", "type": "mc", "subj": "L11", "dom": "D4", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L12-6110", "codes": ["L12102"], "diff": "易", "level": "理解", "fam": "lch-read", "stem": "兩色 CIELAB 分別為 (60, 30, 0) 與 (60, 0, 30)。下列敘述何者正確？", "opts": ["明度相同，彩度相差 30", "明度與彩度相同，只有色相不同", "彩度相同，明度相差 30", "兩色其實完全相同，只是寫法不同"], "explain": "兩者 L* = 60，C* 都是 30；h 分別為 0°（紅方向）與 90°（黃方向），只差在色相。", "trap": "把 a*、b* 的數字差直接當成彩度差。", "src": "科目三指引 1.5；科目二指引 1.2", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L12-6111", "codes": ["L12102", "L12201"], "diff": "中", "level": "應用", "fam": "scheme-lab", "stem": "主色 CIELAB 為 (70, −20, 20)。要做「色調差配色法」（同色相、不同色調），下列哪一色最合適？", "opts": ["(40, −30, 30)", "(70, 20, −20)", "(72, −28, 0)", "(70, −10, 30)"], "explain": "主色 h = 135°。(40, −30, 30) 的 h 也是 135°，C* 由 28 升到 42、L* 降 30，同色相不同色調。(70, 20, −20) h = 315°，是相對色相；(72, −28, 0) h = 180°；(70, −10, 30) h ≈ 108°，色相都不同。", "trap": "要先換成 L*C*h 才看得出同色相；結合 LCh 換算與配色法。", "src": "科目二指引 2.3；科目三指引 1.5", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L12-6112", "codes": ["L12102", "L13105", "L13203"], "diff": "難", "level": "分析", "fam": "print-dc", "stem": "品牌綠規格為 LCh (60, 50, 150)。CMYK 打樣後量得 L*a*b* = (60, −38, 20)。下列判讀何者正確？", "opts": ["ΔE*ab ≈ 7.3，主要是彩度下降，色相幾乎不變", "ΔE*ab ≈ 7.3，主要是色相偏移，因為 a*、b* 都改變了", "ΔE*ab ≈ 10.3，主要是明度改變", "兩者數值寫法不同，無法比較色差"], "explain": "規格換成 a*b*：a* = 50 cos150° ≈ −43.3，b* = 50 sin150° = 25。Δa* ≈ +5.3、Δb* = −5，ΔE ≈ 7.3。打樣 C* ≈ 42.9、h ≈ 152°：ΔC* ≈ −7.1，ΔH* ≈ 1.8，主要是彩度下降，符合印刷色域較小的現象。", "trap": "10.3 是把 |Δa*| 與 |Δb*| 直接相加；要能在 LCh 與 Lab 之間來回換算。", "src": "科目三指引 1.5、2.2；科目二指引 2.4", "type": "mc", "subj": "L12", "dom": "D2", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "A"}, {"id": "L13-6101", "codes": ["L13305"], "diff": "易", "level": "理解", "fam": "intent-why", "stem": "色彩管理系統需要「演色意圖」的根本原因是什麼？", "opts": ["描述檔太大，轉換前需要先壓縮", "螢幕亮度不足，需要提高整體對比", "不同軟體的 RGB 數值格式並不相同", "兩端裝置的色域不同，有些色無法再現"], "explain": "各裝置的色彩空間、白點與色域不同，轉換時會有無法完全對應的顏色；演色意圖決定這些顏色（以及整體色域）如何對映。", "trap": "", "src": "徐明景簡報（色域對應的問題）；科目一指引 2.6", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "D"}, {"id": "L13-6102", "codes": ["L13305", "L11402"], "diff": "中", "level": "應用", "fam": "intent", "stem": "資訊圖表用「色相差配色法」區分 6 個類別（同色調、不同色相），要由 RGB 轉為 CMYK，部分類別色超出色域。若希望各類別仍鮮明可分，依指引應選哪一種演色意圖？", "opts": ["感應式", "飽和度式", "相對色度式", "絕對色度式"], "explain": "飽和度式以保持飽和度為優先，適用商業圖案與圖表；類別色的鮮明區分比色度值精確更重要。", "trap": "結合配色（類別要可區分）與演色意圖的用途。", "src": "科目一指引 2.6；科目二指引 2.3", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "B"}, {"id": "L13-6103", "codes": ["L13305", "L13105", "L12201"], "diff": "難", "level": "分析", "fam": "intent-mix", "stem": "一份包裝 PDF 同時有品牌色塊與商品照片。打樣紙與正式用紙紙白相同，客戶要求品牌色與標準的 ΔE00 ≤ 2，照片則要自然。依官方參考指引，下列處理何者最合理？", "opts": ["全部用感應式整體壓縮色域，品牌色自然會落在允差內", "全部改用飽和度式，讓品牌色與照片都更加鮮明", "品牌色用絕對色度式並量 ΔE 驗收；照片用感應式", "不做轉換，直接把 RGB 檔送印刷廠印製就好"], "explain": "品牌色要求色度值準確，紙白相同時依指引用絕對色度式，並以量測確認 ΔE；照片是自然影像，用感應式保留階調。同一份檔案可依物件分別指定。", "trap": "結合演色意圖、色差驗收與色彩計畫的品管；單一意圖無法同時滿足兩種需求。", "src": "科目一指引 2.6；科目三指引 2.2；科目二指引 2.4", "type": "mc", "subj": "L13", "dom": "D7", "origin": "115題庫v3（串講平行題）", "diag": false, "ans": "C"}];
